[100009] = {id = 100009, scroll = 100000, type = 2, teacheid = 0, name = "1-10", cname = "支配者", plot_first = "s_4", plot_last = "0", map = "0", bgm = "4-Battle-moon_MP3", unlock = "0_1", front = "100008", open = "100010_100000", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "【蒼穹戰線】的真面目是用新研製的戰略兵器DOMINATOR直擊原罪的始祖【逆愛】，為此需要把搭載DOMINATOR的卡佳支部方舟發射到近月軌道上，這正是本次作戰卡佳支部的任務……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-4", npctype = 0, npcbanmove = "0", playnumber = 5, recomlevel = 0, bgpicture = "dialog_s-4", reserve = "0", dangerousenemy = "0_0", npcheads = "shidifenni", promptdialog = "通關1-11後解鎖技能升級", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
