[100032] = {id = 100032, scroll = 100001, type = 15, teacheid = 0, name = "2-12", cname = "偏移的軌跡", plot_first = "s_11", plot_last = "0", map = "yueqiubiaomian_boss", bgm = "9-Battle-niai", unlock = "0_1", front = "100031", open = "100033_100001", player = "0", monster = "600000_3_8_0_1_8_1_0_100355_4000_0_0_0_0", consume = "4_100001_8", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "4_500000_1,1_110031_3,1_100000_50,1_100001_5000", drop = "0", victory = "4_100000_80,1_100001_320", roleexp = "4_100002_80", failure = "4_100001_8", introduction = "4月30日下午2點58分48秒，在謎之聲的幫助下，DOMINATOR成功發射……人類終於迎來了漫長的戰爭的勝利，但是為什麼！！……為什麼逆轉錄光線射偏了？！第一發光束，僅僅只摧毀了逆愛身邊的一扇【門】", prohibit = "220307;210806;200303;200304;201104;210306", scrollmappos = "0", prohibitskill = "220307;210806;200303;200304;201104;210306", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 6, recomlevel = 0, bgpicture = "dialog_s-11", reserve = "0", dangerousenemy = "0_0", npcheads = "shidifenni", promptdialog = "通關2-12後解鎖戰鬥掃蕩", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[100033] = {id = 100033, scroll = 100001, type = 2, teacheid = 0, name = "2-13", cname = "謝幕", plot_first = "s_12", plot_last = "0", map = "0", bgm = "4-Battle-moon_MP3", unlock = "0_1", front = "100032", open = "100034_100001", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "原罪的始祖【逆愛】死亡確認，【逆愛】的【子嗣】通過自己的能力擊殺了她，這是歷史上第一次出現原罪擊殺原罪的事例，難道說是……因為【門】被摧毀的緣故？！【子嗣】開始發射第二DOMINATOR……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-12", npctype = 0, npcbanmove = "0", playnumber = 6, recomlevel = 0, bgpicture = "dialog_s-12", reserve = "0", dangerousenemy = "0_0", npcheads = "shidifenni", promptdialog = "通關2-19後解鎖活動與困難本", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
