[100103] = {id = 100103, scroll = 100010, type = 0, teacheid = 0, name = "3-4", cname = "特別聯合", plot_first = "1_3", plot_last = "0", map = "haigang_yewan", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100102", open = "100104_100010", player = "0", monster = "230002_1_25_0_2_10_1_0_100020_1800_0_100220_400_0;210009_2_21_0_2_4_1_0_100020_1800_0_100220_400_0;230002_1_25_0_2_9_1_0_100020_1800_0_100220_400_0;210009_2_21_0_2_1_1_0_100020_1800_0_100220_400_0;220005_1_25_0_2_17_1_0_100020_1800_0_100220_400_0;210016_3_19_0_2_13_1_0_100020_1800_0_100220_400_0;220005_1_25_0_2_16_1_0_100020_1800_0_100220_400_0", consume = "4_100001_12", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_30,1_110081_5,1_100001_3000", drop = "0", victory = "4_100000_120,1_100001_480", roleexp = "4_100002_120", failure = "4_100001_12", introduction = "在朱利烏斯颯爽登場之後，陸續著又來了兩名巨大化的少女。一等兵查麗莎·德·洛蘭與支援型的弗蘭卡，就她們的戰鬥特性我開始擬定剿滅原罪、拯救平民的辦法，希望她們接下的相處能融洽一點。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 7, recomlevel = 0, bgpicture = "dialog_1-3", reserve = "0", dangerousenemy = "13_210016", npcheads = "shidifenni", promptdialog = "通關3-5後解鎖指揮室維護池", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[100104] = {id = 100104, scroll = 100010, type = 0, teacheid = 0, name = "3-5", cname = "問題小隊", plot_first = "1_4", plot_last = "0", map = "haigang_yewan", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100103", open = "100105_100010", player = "0", monster = "210003_1_26_0_2_6_1_0_100020_1800_0_100220_400_0;220005_1_26_0_2_13_1_0_100020_1800_0_100220_400_0;210003_1_26_0_2_2_1_0_100020_1800_0_100220_400_0;220008_2_22_0_2_17_1_0_100020_1800_0_100220_400_0;220008_2_22_0_2_8_1_0_100020_1800_0_100220_400_0;210003_1_26_0_2_1_1_0_100020_1800_0_100220_400_0;210016_3_20_0_2_5_1_0_100020_1800_0_100220_400_0", consume = "4_100001_12", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_30,1_110071_5,1_100001_3000", drop = "0", victory = "4_100000_120,1_100001_480", roleexp = "4_100002_120", failure = "4_100001_12", introduction = "朱利烏斯負責在弗蘭卡能支援到的前沿處理原罪，弗蘭卡活動在隊伍的後方支援，而機動性最高的查麗莎則是處理邊緣或者前線漏掉的原罪，如果能這樣有序地推進就好了，但是查麗莎似乎不滿意……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 7, recomlevel = 0, bgpicture = "dialog_1-4", reserve = "0", dangerousenemy = "0_0", npcheads = "shidifenni", promptdialog = "通關3-5後解鎖指揮室維護池", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[100105] = {id = 100105, scroll = 100010, type = 0, teacheid = 0, name = "3-6", cname = "逆行", plot_first = "1_5", plot_last = "0", map = "haigang_yewan", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100104", open = "100106_100010", player = "0", monster = "210009_2_22_0_2_1_1_0_100020_1800_0_100220_400_0;230002_1_26_0_2_7_1_0_100020_1800_0_100220_400_0;220008_2_22_0_2_18_1_0_100020_1800_0_100220_400_0;210016_3_20_0_2_13_1_0_100020_1800_0_100220_400_0;220005_1_26_0_2_15_1_0_100020_1800_0_100220_400_0;220005_1_26_0_2_5_1_0_100020_1800_0_100220_400_0;210003_1_26_0_2_9_1_0_100020_1800_0_100220_400_0", consume = "4_100001_12", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_30,1_110010_5,1_100001_3000", drop = "0", victory = "4_100000_120,1_100001_480", roleexp = "4_100002_120", failure = "4_100001_12", introduction = "這座城市，化為了煉獄，巨大化的少女和原罪們在廝殺之間無意地波及了周圍，大地在不斷震動著，鋼筋水泥鑄成的大樓在搖晃坍塌，有一位母親與她的女兒走散了……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 7, recomlevel = 0, bgpicture = "dialog_1-5", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
