[100107] = {id = 100107, scroll = 100010, type = 0, teacheid = 0, name = "3-8", cname = "通感者", plot_first = "1_7", plot_last = "0", map = "haigang_yewan", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100106", open = "100108_100010", player = "0", monster = "230002_1_27_0_2_6_1_0_100020_2100_0_100220_400_0;210009_2_23_0_2_17_1_0_100020_2100_0_100220_400_0;230002_1_27_0_2_2_1_0_100020_2100_0_100220_400_0;210009_2_23_0_2_15_1_0_100020_2100_0_100220_400_0;230002_1_27_0_2_10_1_0_100020_2100_0_100220_400_0;210016_3_21_0_2_11_1_0_100020_2100_0_100220_400_0;220005_1_27_0_2_8_1_0_100020_2100_0_100220_400_0", consume = "4_100001_12", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_30,1_110071_5,1_100001_3000", drop = "0", victory = "4_100000_120,1_100001_480", roleexp = "4_100002_120", failure = "4_100001_12", introduction = "同一時間，從對抗原罪的戰爭最前線調任過來的朱利烏斯，也因為在城市中戰鬥而束手束腳，過於在意自己的行為會不會讓正在撤離的人們受傷，為了安撫她的情緒，領航展開了名為【通感】的能力。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 7, recomlevel = 0, bgpicture = "dialog_1-7", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
