[100111] = {id = 100111, scroll = 100010, type = 0, teacheid = 0, name = "3-12", cname = "女武神", plot_first = "1_9", plot_last = "0", map = "haigang_baitian", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100110", open = "100112_100010", player = "0", monster = "200005_2_27_0_2_11_1_0_100020_2400_0_100230_400_0;230003_1_33_0_2_9_1_0_100020_2400_0_100230_400_0;210016_3_24_0_2_13_1_0_100020_2400_0_100230_400_0;200005_2_27_0_2_1_1_0_100020_2400_0_100230_400_0;220014_1_33_0_2_7_1_0_100020_2400_0_100230_400_0;220003_1_33_0_2_16_1_0_100020_2400_0_100230_400_0;220003_1_33_0_2_4_1_0_100020_2400_0_100230_400_0", consume = "4_100001_12", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_30,1_110071_5,1_100001_3000", drop = "0", victory = "4_100000_120,1_100001_480", roleexp = "4_100002_120", failure = "4_100001_12", introduction = "不安，從作戰開始就一直纏繞著我的不安，源自被濃霧完全遮蔽的海面，於此同時，查麗莎終於不再聽從我的命令，自顧自地衝到了朱利烏斯身邊，也即是正面……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 7, recomlevel = 0, bgpicture = "dialog_1-9", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
