[100127] = {id = 100127, scroll = 100011, type = 0, teacheid = 0, name = "4-9", cname = "協同", plot_first = "1_14", plot_last = "1_14e", map = "haigang_huanghun", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100126", open = "100128_100011", player = "0", monster = "230009_2_40_0_2_18_1_0_100020_2900_0_100230_500_0;220009_2_33_0_2_7_1_0_100020_2900_0_100230_500_0;230006_2_33_0_2_16_1_0_100020_2900_0_100230_500_0;210015_3_29_0_2_14_1_0_100020_2900_0_100230_500_0;230009_2_40_0_2_5_1_0_100020_2900_0_100230_500_0;200001_2_40_0_2_2_1_0_100020_2900_0_100230_500_0;220000_2_40_0_2_15_1_0_100020_2900_0_100230_500_0;200001_2_40_0_2_9_1_0_100020_2900_0_100230_500_0", consume = "4_100001_12", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_30,1_110010_5,1_100001_3000", drop = "0", victory = "4_100000_120,1_100001_480", roleexp = "4_100002_120", failure = "4_100001_12", introduction = "雙方互相瞄準對方的頭部，給予對方致命一擊——但這場絕對卻被突如其來的身影中斷了，朱利烏斯及時趕到了現場，螳螂型原罪再度撤走，領航與查麗莎建立了【通感】分擔了她的痛苦……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 8, recomlevel = 0, bgpicture = "dialog_1-14", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[100128] = {id = 100128, scroll = 100011, type = 0, teacheid = 0, name = "4-10", cname = "准罪級", plot_first = "1_15", plot_last = "0", map = "haigang_huanghun", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100127", open = "100129_100011", player = "0", monster = "230009_2_41_0_2_3_1_0_100030_3100_0_100230_500_0;200001_2_41_0_2_5_1_0_100030_3100_0_100230_500_0;230006_2_35_0_2_1_1_0_100030_3100_0_100230_500_0;210008_2_35_0_2_8_1_0_100030_3100_0_100230_500_0;230009_2_41_0_2_17_1_0_100030_3100_0_100230_500_0;210015_3_31_0_2_14_1_0_100030_3100_0_100230_500_0;210002_2_41_0_2_12_1_0_100030_3100_0_100230_500_0;210002_2_41_0_2_10_1_0_100030_3100_0_100230_500_0", consume = "4_100001_12", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_30,1_110081_5,1_100001_3000", drop = "0", victory = "4_100000_120,1_100001_480", roleexp = "4_100002_120", failure = "4_100001_12", introduction = "我一直以來的擔憂成為了現實，准罪級原罪——【索貝克】從海中登陸了，地面部隊的常規火力無法對它造成一絲一毫的傷害，反而激怒了它，而在它發洩一通吼，把目光放在正在撤離的我們身上。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 8, recomlevel = 0, bgpicture = "dialog_1-15", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[100129] = {id = 100129, scroll = 100011, type = 0, teacheid = 0, name = "4-11", cname = "民眾之盾", plot_first = "1_16", plot_last = "0", map = "haigang_huanghun", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100128", open = "100130_100011", player = "0", monster = "200001_2_41_0_2_5_1_0_100030_3100_0_100230_500_0;200009_2_41_0_2_16_1_0_100030_3100_0_100030_500_0;210008_2_35_0_2_10_1_0_100030_3100_0_100230_500_0;210015_3_31_0_2_11_1_0_100030_3100_0_100230_500_0;200009_2_41_0_2_18_1_0_100030_3100_0_100030_500_0;220000_2_41_0_2_12_1_0_100030_3100_0_100230_500_0;220000_2_41_0_2_3_1_0_100030_3100_0_100230_500_0;220009_2_35_0_2_8_1_0_100030_3100_0_100230_500_0", consume = "4_100001_12", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_30,1_110071_5,1_100001_3000", drop = "0", victory = "4_100000_120,1_100001_480", roleexp = "4_100002_120", failure = "4_100001_12", introduction = "預計在五分鐘後，【索貝爾】會與我們小隊進行第一次接觸，我下了一個決斷，讓查麗莎迅速清理周邊的原罪的，然後讓平民們先撤離，我們要在這裡攔下【索貝爾】！", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 8, recomlevel = 0, bgpicture = "dialog_1-16", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
