[100218] = {id = 100218, scroll = 100020, type = 0, teacheid = 0, name = "5-19", cname = "回憶補時", plot_first = "2_7", plot_last = "0", map = "haizhan_yewan", bgm = "20-Battle-Warehouse2_MP3", unlock = "0_1", front = "100217", open = "100219_100020", player = "0", monster = "200003_2_45_0_3_1_1_0_100031_4000_0_100240_1500_0;230008_2_49_0_3_7_1_0_100031_4000_0_100240_1500_0;220002_3_40_0_3_15_1_0_100031_4000_0_100240_1500_0;220002_3_40_0_3_9_1_0_100031_4000_0_100240_1500_0;210004_2_49_0_3_12_1_0_100031_4000_0_100240_1500_0;200003_2_45_0_3_5_1_0_100031_4000_0_100240_1500_0;220001_2_49_0_3_3_1_0_100031_4000_0_100240_1500_0;210004_2_49_0_3_11_1_0_100031_4000_0_100240_1500_0;200006_2_45_0_3_17_1_0_100031_4000_0_100240_1500_0", consume = "4_100001_16", frequency = 0, condition = "0_9_1,2_40_19,0_2_12", reward = "1_100000_30,1_110072_5,1_100001_3000", drop = "0", victory = "4_100000_160,1_100001_640", roleexp = "4_100002_160", failure = "4_100001_16", introduction = "消滅了沿路的原罪後，我觀測到了兩個強大的尼姆比斯能源反應，推測一隻是【高等原罪】，另一隻是月冕小隊觀測到的巨大原罪，此時多洛莉絲的記憶回流，察覺到她狀態不對，我們決定返航。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_2-7", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
