[100222] = {id = 100222, scroll = 100020, type = 0, teacheid = 0, name = "5-23", cname = "安潔莉卡", plot_first = "2_8", plot_last = "2_8e", map = "haizhan_yewan", bgm = "20-Battle-Warehouse2_MP3", unlock = "0_1", front = "100221", open = "100223_100020", player = "0", monster = "220002_3_42_0_3_3_1_0_100031_4100_0_100240_1500_0;220001_2_50_0_3_18_1_0_100031_4100_0_100240_1500_0;200003_2_47_0_3_8_1_0_100031_4100_0_100240_1500_0;210004_2_50_0_3_4_1_0_100031_4100_0_100240_1500_0;230008_2_50_0_3_7_1_0_100031_4100_0_100240_1500_0;200003_2_47_0_3_12_1_0_100031_4100_0_100240_1500_0;210004_2_50_0_3_13_1_0_100031_4100_0_100240_1500_0;200006_2_47_0_3_17_1_0_100031_4100_0_100240_1500_0;220002_3_42_0_3_11_1_0_100031_4100_0_100240_1500_0", consume = "4_100001_16", frequency = 0, condition = "0_9_1,2_40_19,0_2_12", reward = "1_100000_30,1_110010_5,1_100001_3000", drop = "0", victory = "4_100000_160,1_100001_640", roleexp = "4_100002_160", failure = "4_100001_16", introduction = "原罪潛伏在我們返程路上，像是有預謀地針對著我們發起襲擊，我為了緩解多洛莉絲的痛苦，與她建立了【通感】，悲傷到近乎哀慟的情緒如河流般奔入我的腦中……隨後我們遭遇了巨大的原罪——", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_2-8", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[100223] = {id = 100223, scroll = 100020, type = 0, teacheid = 0, name = "5-24", cname = "第一類接觸", plot_first = "0", plot_last = "2_9e", map = "haizhan_yewan", bgm = "20-Battle-Warehouse2_MP3", unlock = "0_1", front = "100222", open = "100224_100020", player = "0", monster = "210009_2_47_0_3_3_1_0_100031_4100_0_100240_1500_0;220005_2_50_0_3_2_1_0_100031_4100_0_100240_1500_0;200012_2_50_0_3_18_1_0_100031_4100_0_100240_1500_0;220003_2_50_0_3_6_1_0_100031_4100_0_100240_1500_0;200008_3_42_0_3_16_1_0_100031_4100_0_100240_1500_0;220009_2_47_0_3_12_1_0_100031_4100_0_100240_1500_0;210015_3_42_0_3_17_1_0_100031_4100_0_100240_1500_0;220005_2_50_0_3_1_1_0_100031_4100_0_100240_1500_0;210009_2_47_0_3_8_1_0_100031_4100_0_100240_1500_0", consume = "4_100001_16", frequency = 0, condition = "0_9_1,2_40_19,0_2_12", reward = "1_100000_30,1_110082_5,1_100001_3000", drop = "0", victory = "4_100000_160,1_100001_640", roleexp = "4_100002_160", failure = "4_100001_16", introduction = "我們與海蛇般的巨大原罪展開了交鋒，但是我們之前已經經歷過幾輪戰鬥，剩下的尼姆比斯液不足以支撐我們進行一場討伐戰，在查麗莎找到機會給予巨大原罪創傷的時候，我們選擇了迅速撤離……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_2-9", reserve = "0", dangerousenemy = "16_200008", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[100224] = {id = 100224, scroll = 100020, type = 2, teacheid = 0, name = "5-25", cname = "幕間Ⅰ", plot_first = "2_10", plot_last = "0", map = "0", bgm = "20-Battle-Warehouse2_MP3", unlock = "0_1", front = "100223", open = "100225_100020", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "恐懼、絕望、哀痛，以及——勇氣，這是我對這段記憶主觀到可以說是一己之見的印象，第三研究院防衛隊隊長，安潔莉卡的故事拉開了序幕，而又快速落幕……真的落幕了嗎……？", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_2-10", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_2-10", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[100225] = {id = 100225, scroll = 100020, type = 0, teacheid = 0, name = "5-26", cname = "逃走的意義", plot_first = "2_11", plot_last = "0", map = "haizhan_yewan", bgm = "20-Battle-Warehouse2_MP3", unlock = "0_1", front = "100224", open = "100226_100020", player = "0", monster = "210015_3_42_0_3_14_1_0_100031_4100_0_100240_1500_0;220009_2_47_0_3_12_1_0_100031_4100_0_100240_1500_0;200008_3_42_0_3_5_1_0_100031_4100_0_100240_1500_0;210009_2_47_0_3_2_1_0_100031_4100_0_100240_1500_0;210009_2_47_0_3_3_1_0_100031_4100_0_100240_1500_0;220005_2_50_0_3_9_1_0_100031_4100_0_100240_1500_0;220005_2_50_0_3_18_1_0_100031_4100_0_100240_1500_0;200012_2_50_0_3_7_1_0_100031_4100_0_100240_1500_0;220003_2_50_0_3_16_1_0_100031_4100_0_100240_1500_0", consume = "4_100001_16", frequency = 0, condition = "0_9_1,2_40_19,0_2_12", reward = "1_100000_30,1_110072_5,1_100001_3000", drop = "0", victory = "4_100000_160,1_100001_640", roleexp = "4_100002_160", failure = "4_100001_16", introduction = "我們在蒼霧的週邊遇見了等待著我們的月冕小隊，此時的多洛莉絲也終於從痛苦中緩和了過了，並找回了屬於她的記憶，屬於她的使命——她是一一枚鑰匙，只有她能開通通往第三實驗室的大門。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_2-11", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[100226] = {id = 100226, scroll = 100020, type = 2, teacheid = 0, name = "5-27", cname = "救世主", plot_first = "2_12", plot_last = "0", map = "0", bgm = "20-Battle-Warehouse2_MP3", unlock = "0_1", front = "100225", open = "100227_100020", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "第三研究院防衛隊的隊長，為了保護核心區的核心，啟動了防禦系統，使得我們有二十四小時的準備時間來攻破第三研究院，但眼下，被命名為【耶夢加得】的巨蛇是我們目前最大的阻礙。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_2-12", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_2-12", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[100227] = {id = 100227, scroll = 100020, type = 2, teacheid = 0, name = "5-28", cname = "幕間Ⅱ", plot_first = "2_13", plot_last = "0", map = "0", bgm = "20-Battle-Warehouse2_MP3", unlock = "0_1", front = "100226", open = "100228_100021", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "第三研究院防衛隊的成員們在蒼霧的影響下漸漸失去了自己的記憶，但是，不知道有什麼力量、什麼東西、什麼想法，讓她們一直在苦苦支撐著、支撐著……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_2-13", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_2-13", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
