[100346] = {id = 100346, scroll = 100031, type = 15, teacheid = 0, name = "8-23", cname = "嫉妒", plot_first = "3_18", plot_last = "0", map = "yanjiushi_boss", bgm = "17-Battle-jidu_MP3", unlock = "0_1", front = "100345", open = "100347_100031", player = "0", monster = "600003_4_80_1_6_8_1_0_100155_2500_0_100355_5000_0", consume = "4_100001_16", frequency = 0, condition = "0_9_1,2_40_19,0_1_2", reward = "4_500003_1,1_110031_3,4_90000003_1,1_100000_50,1_100001_5000", drop = "0", victory = "4_100000_160,1_100001_640", roleexp = "4_100002_160", failure = "4_100001_16", introduction = "我將成為第三研究室防衛班最後的...以及新生的盾。", prohibit = "220307;210806;211603;211604;211807;220201;230302;201007", scrollmappos = "0", prohibitskill = "220307;210806;211603;211604;211807;220201;230302;201007", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_3-18", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[100347] = {id = 100347, scroll = 100031, type = 2, teacheid = 0, name = "8-24", cname = "船長與船", plot_first = "3_19", plot_last = "0", map = "0", bgm = "4-Battle-moon_MP3", unlock = "0_1", front = "100346", open = "100348_100031", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "被【逆愛】欺騙。又被【貪婪】蠱惑，高等原罪【嫉妒】，死在了這裡。多洛莉絲決定留下來完成她最後的使命。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_3-19", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_3-19", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[100348] = {id = 100348, scroll = 100031, type = 2, teacheid = 0, name = "8-25", cname = "活存餘溫", plot_first = "3_20", plot_last = "0", map = "0", bgm = "4-Battle-moon_MP3", unlock = "0_1", front = "100347", open = "100400_100040", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "多瑙特別聯合部隊，返航。多洛莉絲，未歸隊。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_3-20", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_3-20", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[100400] = {id = 100400, scroll = 100040, type = 2, teacheid = 0, name = "9-1", cname = "隕落的方舟", plot_first = "4_1", plot_last = "0", map = "0", bgm = "42-Battle-crisis", unlock = "0_1", front = "100348", open = "100401_100040", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "我們乘坐運輸機來到被原罪摧殘過後的瑪雅首都。透過玻璃窗口我們看到——原本宏偉的瑪雅方舟裂成兩瓣，如斷裂的墓碑般嵌在殘垣廢墟之中……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_4-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[100401] = {id = 100401, scroll = 100040, type = 2, teacheid = 0, name = "9-2", cname = "秘書小姐-1", plot_first = "4_2", plot_last = "0", map = "0", bgm = "42-Battle-crisis", unlock = "0_1", front = "100400", open = "100402_100040", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "運輸機安然地穿過蒼霧區，降落到避難所的停機坪上。倖存的人們聚集在此熱情地迎接我們的到來，他們好像並沒有沉溺在失去家園的悲傷之中。從接待我們的秘書小姐口中得知，支撐這一切的人是一位叫奧德賽的瑪雅名人……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_4-2", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
