[100425] = {id = 100425, scroll = 100040, type = 2, teacheid = 0, name = "9-26", cname = "異變", plot_first = "4_10", plot_last = "0", map = "0", bgm = "42-Battle-crisis", unlock = "0_1", front = "100424", open = "100426_100041", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "返回避難所後，我們遭受了一場意料之外的襲擊。襲擊者是難民中的一位女性，她受到蒼霧的感染開始變成原罪。這進一步證實了駕駛員會受感染變成原罪的事實，也讓我下定了重啟【幽靈】的決心……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_4-10", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[100426] = {id = 100426, scroll = 100041, type = 2, teacheid = 0, name = "10-1", cname = "贖罪", plot_first = "4_11", plot_last = "0", map = "0", bgm = "42-Battle-crisis", unlock = "0_1", front = "100425", open = "100427_100041", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在秘書小姐被襲擊時奧德賽奮不顧身的反應，不僅我感覺奇怪，就連查麗莎都感到不對勁。經過簡單的推導，奧德賽大叔或許是被“贖罪”心理影響，而這個贖罪的原因和他之前向我們隱瞞的事情有關……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_4-11", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
