[800400] = {id = 800400, scroll = 800400, type = 105, teacheid = 0, name = "1-1", cname = "弗蘭卡、弗蘭卡、還是弗蘭卡", plot_first = "gerenjuqing_plot/grjq_fulanka/grjq_fulanka_1", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0", front = "0", open = "0", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "0", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "今天，領航將於弗蘭卡一起進行全面的“精神狀態”檢定，不出意外的話，這是只需要花費數小時就能完成的檢查……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
