[900229] = {id = 900229, scroll = 900202, type = 103, teacheid = 0, name = "3-5", cname = "【冥河】討伐戰·困難", plot_first = "0", plot_last = "0", map = "yuemian", bgm = "35-Hazy", unlock = "1_910005", front = "900228", open = "0", player = "0", monster = "600008_5_90_1_6_8_1_0_100155_6500_0_100355_10000_0", consume = "4_100001_25", frequency = 0, condition = "0_9_1,2_35_10,0_1_2", reward = "1_100000_50,1_100001_5000", drop = "0", victory = "4_100000_250,1_100001_1000", roleexp = "4_100002_250", failure = "4_100001_25", introduction = "4月30日下午2點58分48秒，在謎之聲的幫助下，DOMINATOR成功發射……人類終於迎來了漫長的戰爭的勝利，但是為什麼！！……為什麼逆轉錄光線射偏了？！第一發光束，僅僅只摧毀了逆愛身邊的一扇【門】", prohibit = "220307;210806;200303;200304;201104;210306", scrollmappos = "0", prohibitskill = "220307;210806;200303;200304;201104;210306", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900230] = {id = 900230, scroll = 900203, type = 2, teacheid = 0, name = "1", cname = "流浪貓與偽通感者們", plot_first = "Huo@dongPlot/YueMian/YM_1_1", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "0", open = "900231_900203", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "【嫉妒】事件之後，艾吉斯召集了駕駛員處理薩爾市近海的防衛與清理工作，在會議之後主持會議的洛尼絲要求月冕的隊長摩根勒菲單獨留下來，並遞給了她一張女孩的照片，洛尼絲希望她能救救照片中的女孩——芙露露。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900231] = {id = 900231, scroll = 900203, type = 2, teacheid = 0, name = "2", cname = "“保姆”", plot_first = "Huo@dongPlot/YueMian/YM_1_2", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900230", open = "900232_900203", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "身世充滿謎團的芙露露正式成為了月冕小隊的一員，新的月冕小隊準備進行第一次作戰。與此同時，莉莉絲與斯卡蒂拜託領航尋找芙露露的真正檔案。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900232] = {id = 900232, scroll = 900203, type = 2, teacheid = 0, name = "3", cname = "海岸上哭泣的少女", plot_first = "Huo@dongPlot/YueMian/YM_1_3", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900231", open = "900233_900203", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "作戰結束，月冕小隊將海面上大部分的水母殲滅，但是不知為何，除了摩根勒菲之外，所有人似乎都被那螢光色的海水迷住了，她們駐留在海灘上久久不忍離去……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900233] = {id = 900233, scroll = 900203, type = 2, teacheid = 0, name = "4", cname = "以小小溫暖對抗", plot_first = "Huo@dongPlot/YueMian/YM_1_4", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900232", open = "900234_900203", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "莉莉絲帶來了搜集來的芙露露的資料，還有她父母的資料，莉莉絲斷定芙露露通過幻象看到了什麼，並沉浸在其中，她想讓芙露露擺脫幻想。在她為“魔術”做準備的時候，從洛尼絲那裡得知芙露露擅自幻化參與了收尾工作。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_4", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900234] = {id = 900234, scroll = 900203, type = 2, teacheid = 0, name = "5", cname = "少女停止了流淚", plot_first = "Huo@dongPlot/YueMian/YM_1_5", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900233", open = "900235_900203", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "海灘上最後僅存的水母們開始了【進化】，原罪們瘋狂地集中在一起，把一小塊區域化作了怪誕的絞肉機，它們展開最後了的反擊。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_5", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900235] = {id = 900235, scroll = 900203, type = 2, teacheid = 0, name = "6", cname = "芙露露看見了", plot_first = "Huo@dongPlot/YueMian/YM_1_6", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900234", open = "900236_900203", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "月冕小隊作為緊急處理小隊參與了討伐戰，洛尼絲提議讓芙露露隨著大部隊撤離，但是月冕小隊遵從了芙露露的意志，讓她留在了戰場。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900236] = {id = 900236, scroll = 900203, type = 2, teacheid = 0, name = "7", cname = "月冕", plot_first = "Huo@dongPlot/YueMian/YM_1_7", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900235", open = "900237_900203", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "最初的芙露露難以融入月冕的戰鬥節奏，在摩根勒菲和莉莉絲的引導下，第一次主動進入【偽通感】狀態，與斯卡蒂一起擊破了巨大原罪的觸手。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_7", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900237] = {id = 900237, scroll = 900203, type = 2, teacheid = 0, name = "8", cname = "第四位魔法少女", plot_first = "Huo@dongPlot/YueMian/YM_1_8", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900236", open = "900238_900203", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "戰後，芙露露收穫了即使不用通感也能體會到的溫暖感情——寄給“月冕”的感謝信，並且暫時地找到了自己想要幹的事情，沒有目標的她想要繼承父母的目標，也是所有人的最終目標，驅逐原罪，奪回人類的家園。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_8", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900238] = {id = 900238, scroll = 900203, type = 15, teacheid = 0, name = "9", cname = "【冥河】討伐戰", plot_first = "0", plot_last = "0", map = "yuemian", bgm = "35-Hazy", unlock = "0,1", front = "900237", open = "0", player = "0", monster = "600008_4_55_1_5_8_1_0_100155_3000_0_100355_3000_0", consume = "4_100001_16", frequency = 0, condition = "2_70_34,2_80_34,2_90_34", reward = "1_100000_10", drop = "0", victory = "4_200014_50,4_100000_160,1_100001_640", roleexp = "4_100002_160", failure = "4_100001_16", introduction = "0", prohibit = "220307;210806;200303;200304;201104;210306", scrollmappos = "0", prohibitskill = "220307;210806;200303;200304;201104;210306", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900301] = {id = 900301, scroll = 900300, type = 105, teacheid = 0, name = "1-1", cname = "蛻皮之蛇", plot_first = "Huo@dongPlot/HaiDao/SF_1", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "1_910004", front = "0", open = "900302_900300", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在過去的戰役中，耶夢加得被多瑙聯合部隊擊敗——但似乎看起來，這條蛇並沒有像報告中那樣老實地死去……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900302] = {id = 900302, scroll = 900300, type = 105, teacheid = 0, name = "1-2", cname = "少女與駕駛員", plot_first = "Huo@dongPlot/HaiDao/SF_2", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "1_910004", front = "900301", open = "900303_900300", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "自出生以來便一直居住在海島的少女——莉比蒂萌生出要離開家鄉的想法，但此時此刻，她卻面臨著空前的危機……原罪。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900303] = {id = 900303, scroll = 900300, type = 105, teacheid = 0, name = "1-3", cname = "“天神”", plot_first = "Huo@dongPlot/HaiDao/SF_3", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "1_910004", front = "900302", open = "900304_900300", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在危機中拯救了莉比蒂的人正是格洛麗亞、羅德尼亞、靜三名駕駛員組成的地區聯合調查小隊，但莉比蒂卻稱呼她們為“天神的使徒”。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900304] = {id = 900304, scroll = 900300, type = 105, teacheid = 0, name = "1-4", cname = "要做多餘的事情", plot_first = "Huo@dongPlot/HaiDao/SF_4", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "1_910004", front = "900303", open = "900305_900300", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在三周前，一直鮮有人拜訪的海島迎來了它久違的訪客，但這位訪客是一名不速之客……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_4", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900305] = {id = 900305, scroll = 900300, type = 107, teacheid = 0, name = "1-5", cname = "不開玩笑", plot_first = "Huo@dongPlot/HaiDao/SF_5", plot_last = "Huo@dongPlot/HaiDao/SF_5e", map = "senling", bgm = "38-Battle-island", unlock = "1_910004", front = "900304", open = "900306_900300", player = "11034_3_50_0_5_0_1_0_0_0_0_0_0_0;12001_3_50_0_5_0_1_0_0_0_0_0_0_0;10012_3_50_0_5_0_1_0_0_0_0_0_0_0", monster = "230003_2_35_0_3_18_1_0_100030_3500_0_100030_2900_0;210002_1_30_0_3_7_1_0_100031_3500_0_100031_2900_0;220008_2_35_0_3_17_1_0_100030_3500_0_100030_2900_0;210002_1_30_0_3_13_1_0_100031_3500_0_100031_2900_0;200002_3_35_0_3_3_1_0_100431_3500_0_100431_2900_0;200000_1_35_0_3_5_1_0_100030_3500_0_100030_2900_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_666_34,0_9_33", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "地區聯合調查小隊拜訪了莉比蒂居住的村莊，卻遭到了意想不到的阻力。看起來，這裡的人十分排斥不請自來的外來人。正當她們一籌莫展之際，原罪再度襲來。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_5", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900306] = {id = 900306, scroll = 900300, type = 105, teacheid = 0, name = "1-6", cname = "突出的優點", plot_first = "Huo@dongPlot/HaiDao/SF_6", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "1_910004", front = "900305", open = "900307_900300", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在村莊遭受不可抗阻力的調查小隊，接到了趕來支援的駕駛員愛麗絲·克雷蒂亞的通知。在一番交流後，她們決定放棄調查，專心保護村莊，可就在這時，靜提出了自己的猜想……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900307] = {id = 900307, scroll = 900300, type = 107, teacheid = 0, name = "1-7", cname = "新生第三研究室防衛班", plot_first = "Huo@dongPlot/HaiDao/SF_7", plot_last = "Huo@dongPlot/HaiDao/SF_7e", map = "senling", bgm = "38-Battle-island", unlock = "1_910004", front = "900306", open = "900308_900300", player = "11034_3_50_0_5_0_1_0_0_0_0_0_0_0;12001_3_50_0_5_0_1_0_0_0_0_0_0_0;10012_3_50_0_5_0_1_0_0_0_0_0_0_0", monster = "230006_3_35_0_3_17_1_0_100031_3700_0_100030_3100_0;210008_2_40_0_3_7_1_0_100032_3700_0_100031_3100_0;200000_1_46_0_3_2_1_0_100432_3700_0_100431_3100_0;210006_2_40_0_3_4_1_0_100032_3700_0_100031_3100_0;220004_1_46_0_3_8_1_0_100032_3700_0_100031_3100_0;220004_1_46_0_3_11_1_0_100032_3700_0_100031_3100_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_666_34,0_9_33", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "羅德尼亞與靜被派去調查神廟，在路途上，靜通過交談得知了羅德尼亞與格洛麗亞來自於第三研究室防衛班——那隻在一個月前幾乎全員陣亡的小隊。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_7", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900308] = {id = 900308, scroll = 900300, type = 105, teacheid = 0, name = "1-8", cname = "這是我們的爛攤子", plot_first = "Huo@dongPlot/HaiDao/SF_8", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "1_910004", front = "900307", open = "900309_900300", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“耶夢加得”——本應在一個月前死去的原罪再一次出現在了人類的面前。指揮室做出指示讓三人撤離，“它是我們的爛攤子”，這是羅德尼亞的回答。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_8", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900309] = {id = 900309, scroll = 900300, type = 108, teacheid = 0, name = "1-9", cname = "約定的份量", plot_first = "Huo@dongPlot/HaiDao/SF_8e", plot_last = "Huo@dongPlot/HaiDao/SF_9", map = "senling_huanghun_boss", bgm = "16-Battle-Jormungand_MP3", unlock = "1_910004", front = "900308", open = "0", player = "11034_6_90_1_1_0_1_0_0_0_0_0_0_0", monster = "600009_2_20_0_1_8_1_0_0_0_0_100255_2000_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_666_34,0_9_33", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "不管怎樣的絕境，羅德尼亞都必須要站起來，因為她是一個遵守約定的人。現在，她要履行“揍飛耶夢加得”的約定。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_9", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
