[900334] = {id = 900334, scroll = 900302, type = 103, teacheid = 0, name = "3-5", cname = "【耶夢加得】討伐戰·困難", plot_first = "0", plot_last = "0", map = "senling_huanghun_boss", bgm = "16-Battle-Jormungand_MP3", unlock = "1_910005", front = "900333", open = "0", player = "0", monster = "600009_5_90_1_6_8_1_0_100155_6500_0_100355_10000_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_35_10,0_1_2", reward = "1_100000_50,1_100001_5000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "4月30日下午2點58分48秒，在謎之聲的幫助下，DOMINATOR成功發射……人類終於迎來了漫長的戰爭的勝利，但是為什麼！！……為什麼逆轉錄光線射偏了？！第一發光束，僅僅只摧毀了逆愛身邊的一扇【門】", prohibit = "220307;210806;211603;211604;202101;200800;200801;210200;211707;221000;221001", scrollmappos = "0", prohibitskill = "220307;210806;211603;211604;202101;200800;200801;210200;211707;221000;221001", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900335] = {id = 900335, scroll = 900303, type = 2, teacheid = 0, name = "1", cname = "蛻皮之蛇", plot_first = "Huo@dongPlot/HaiDao/SF_1", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "0", open = "900336_900303", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在過去的戰役中，耶夢加得被多瑙聯合部隊擊敗——但似乎看起來，這條蛇並沒有像報告中那樣老實地死去……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900336] = {id = 900336, scroll = 900303, type = 2, teacheid = 0, name = "2", cname = "少女與駕駛員", plot_first = "Huo@dongPlot/HaiDao/SF_2", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900335", open = "900337_900303", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "自出生以來便一直居住在海島的少女——莉比蒂萌生出要離開家鄉的想法，但此時此刻，她卻面臨著空前的危機……原罪。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900337] = {id = 900337, scroll = 900303, type = 2, teacheid = 0, name = "3", cname = "“天神”", plot_first = "Huo@dongPlot/HaiDao/SF_3", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900336", open = "900338_900303", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在危機中拯救了莉比蒂的人正是格洛麗亞、羅德尼亞、靜三名駕駛員組成的地區聯合調查小隊，但莉比蒂卻稱呼她們為“天神的使徒”。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900338] = {id = 900338, scroll = 900303, type = 2, teacheid = 0, name = "4", cname = "要做多餘的事情", plot_first = "Huo@dongPlot/HaiDao/SF_4", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900337", open = "900339_900303", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在三周前，一直鮮有人拜訪的海島迎來了它久違的訪客，但這位訪客是一名不速之客……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_4", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900339] = {id = 900339, scroll = 900303, type = 999, teacheid = 0, name = "5", cname = "不開玩笑", plot_first = "Huo@dongPlot/HaiDao/SF_5", plot_last = "Huo@dongPlot/HaiDao/SF_5e", map = "senling", bgm = "38-Battle-island", unlock = "0,1", front = "900338", open = "900340_900303", player = "11034_3_50_0_5_0_1_0_0_0_0_0_0_0;12001_3_50_0_5_0_1_0_0_0_0_0_0_0;10012_3_50_0_5_0_1_0_0_0_0_0_0_0", monster = "230003_2_35_0_3_18_1_0_100030_3500_0_100030_2900_0;210002_1_30_0_3_7_1_0_100031_3500_0_100031_2900_0;220008_2_35_0_3_17_1_0_100030_3500_0_100030_2900_0;210002_1_30_0_3_13_1_0_100031_3500_0_100031_2900_0;200002_3_35_0_3_3_1_0_100431_3500_0_100431_2900_0;200000_1_35_0_3_5_1_0_100030_3500_0_100030_2900_0", consume = "4_100001_0", frequency = 0, condition = "2_70_34,2_80_34,2_90_34", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "地區聯合調查小隊拜訪了莉比蒂居住的村莊，卻遭到了意想不到的阻力。看起來，這裡的人十分排斥不請自來的外來人。正當她們一籌莫展之際，原罪再度襲來。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_5", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900340] = {id = 900340, scroll = 900303, type = 2, teacheid = 0, name = "6", cname = "突出的優點", plot_first = "Huo@dongPlot/HaiDao/SF_6", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900339", open = "900341_900303", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在村莊遭受不可抗阻力的調查小隊，接到了趕來支援的駕駛員愛麗絲·克雷蒂亞的通知。在一番交流後，她們決定放棄調查，專心保護村莊，可就在這時，靜提出了自己的猜想……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900341] = {id = 900341, scroll = 900303, type = 999, teacheid = 0, name = "7", cname = "新生第三研究室防衛班", plot_first = "Huo@dongPlot/HaiDao/SF_7", plot_last = "Huo@dongPlot/HaiDao/SF_7e", map = "senling", bgm = "38-Battle-island", unlock = "0,1", front = "900340", open = "900342_900303", player = "11034_3_50_0_5_0_1_0_0_0_0_0_0_0;12001_3_50_0_5_0_1_0_0_0_0_0_0_0;10012_3_50_0_5_0_1_0_0_0_0_0_0_0", monster = "230006_3_35_0_3_17_1_0_100031_3700_0_100030_3100_0;210008_2_40_0_3_7_1_0_100032_3700_0_100031_3100_0;200000_1_46_0_3_2_1_0_100432_3700_0_100431_3100_0;210006_2_40_0_3_4_1_0_100032_3700_0_100031_3100_0;220004_1_46_0_3_8_1_0_100032_3700_0_100031_3100_0;220004_1_46_0_3_11_1_0_100032_3700_0_100031_3100_0", consume = "4_100001_0", frequency = 0, condition = "2_70_34,2_80_34,2_90_34", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "羅德尼亞與靜被派去調查神廟，在路途上，靜通過交談得知了羅德尼亞與格洛麗亞來自於第三研究室防衛班——那隻在一個月前幾乎全員陣亡的小隊。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_7", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900342] = {id = 900342, scroll = 900303, type = 2, teacheid = 0, name = "8", cname = "這是我們的爛攤子", plot_first = "Huo@dongPlot/HaiDao/SF_8", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900341", open = "900343_900303", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“耶夢加得”——本應在一個月前死去的原罪再一次出現在了人類的面前。指揮室做出指示讓三人撤離，“它是我們的爛攤子”，這是羅德尼亞的回答。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_8", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900343] = {id = 900343, scroll = 900303, type = 998, teacheid = 0, name = "9", cname = "約定的份量", plot_first = "Huo@dongPlot/HaiDao/SF_8e", plot_last = "Huo@dongPlot/HaiDao/SF_9", map = "senling_huanghun_boss", bgm = "16-Battle-Jormungand_MP3", unlock = "0,1", front = "900342", open = "900344_900303", player = "11034_6_90_1_1_0_1_0_0_0_0_0_0_0", monster = "600009_2_20_0_1_8_1_0_0_0_0_100255_2000_0", consume = "4_100001_0", frequency = 0, condition = "2_70_34,2_80_34,2_90_34", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "不管怎樣的絕境，羅德尼亞都必須要站起來，因為她是一個遵守約定的人。現在，她要履行“揍飛耶夢加得”的約定。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_9", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900344] = {id = 900344, scroll = 900303, type = 15, teacheid = 0, name = "10", cname = "【耶夢加得】討伐戰", plot_first = "0", plot_last = "0", map = "senling_huanghun_boss", bgm = "16-Battle-Jormungand_MP3", unlock = "0,1", front = "900343", open = "0", player = "0", monster = "600009_4_55_1_5_8_1_0_100155_3000_0_100355_3000_0", consume = "4_100001_16", frequency = 0, condition = "2_70_34,2_80_34,2_90_34", reward = "1_100000_10", drop = "0", victory = "4_200015_50,4_100000_160,1_100001_640", roleexp = "4_100002_160", failure = "4_100001_16", introduction = "0", prohibit = "220307;210806;211603;211604;202101;200800;200801;210200;211707;221000;221001", scrollmappos = "0", prohibitskill = "220307;210806;211603;211604;202101;200800;200801;210200;211707;221000;221001", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900501] = {id = 900501, scroll = 900500, type = 107, teacheid = 0, name = "1-1", cname = "救援信號", plot_first = "Huo@dongPlot/XueXiao/xue_1", plot_last = "Huo@dongPlot/XueXiao/xue_1e", map = "xuedi_yewan", bgm = "50-snowbattle", unlock = "1_910004", front = "0", open = "900502_900500", player = "13005_3_50_0_5_0_1_0_0_0_0_0_0_0;13014_3_50_0_5_0_1_0_0_0_0_0_0_0;11007_3_50_0_5_0_1_0_0_0_0_0_0_0", monster = "220015_3_30_0_5_12_1_0_100031_3300_0_100031_2700_0;210010_3_30_0_3_6_1_0_100031_3300_0_100031_2700_0;220009_2_34_0_3_16_1_0_100031_3300_0_100031_2700_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_666_34,0_9_33", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "接收到斷斷續續的救援信號，雪鸮小隊頂著十年難遇的暴風雪前往調查。可是在前往信號來源處的路途中遭受了不明敵人的攻擊。大雪遮蔽了敵人的一切，唯一可以確定的是，敵人是個原罪……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900502] = {id = 900502, scroll = 900500, type = 105, teacheid = 0, name = "1-2", cname = "意外情況", plot_first = "Huo@dongPlot/XueXiao/xue_2", plot_last = "0", map = "0", bgm = "50-snowbattle", unlock = "1_910004", front = "900501", open = "900503_900500", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在莉迪婭的掩護斷後下，熱尼亞與莫莫卡順利找到了發出救援信號的位置，而信號的發出者竟是瓦爾基裏小隊的隊員莉法。但出乎二人意料的是，這裏除了莉法之外還困著更多人……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900503] = {id = 900503, scroll = 900500, type = 105, teacheid = 0, name = "1-3", cname = "停電", plot_first = "Huo@dongPlot/XueXiao/xue_3", plot_last = "0", map = "0", bgm = "50-snowbattle", unlock = "1_910004", front = "900502", open = "900504_900500", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "莉迪婭僥倖擺脫了原罪，拖著傷痕累累的身體撐到了冰炬基地，同事也帶來了有關原罪的些許資訊。就在幾人商討接下來如何行動之時，基地的能源卻出現了問題……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900504] = {id = 900504, scroll = 900500, type = 105, teacheid = 0, name = "1-4", cname = "基地深處", plot_first = "Huo@dongPlot/XueXiao/xue_4", plot_last = "0", map = "0", bgm = "50-snowbattle", unlock = "1_910004", front = "900503", open = "900505_900500", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "三人輕鬆擊殺掉侵入的原罪，來到了基地的深處。展現在三人眼前的是一個時代的淚痕，一個曾經製造了歷史上最嚴重的人造災難的裝置——尼姆比斯電場發生器……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_4", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900505] = {id = 900505, scroll = 900500, type = 105, teacheid = 0, name = "1-5", cname = "另一方向", plot_first = "Huo@dongPlot/XueXiao/xue_5", plot_last = "0", map = "0", bgm = "50-snowbattle", unlock = "1_910004", front = "900504", open = "900506_900500", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "通過損壞的門，三人發現了基地後方的出口。在離這不遠的地方就有一座樞紐城市……就在幾人商討下一步行動時，一種悄然的襲擊正在侵蝕熱尼亞的核心……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_5", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900506] = {id = 900506, scroll = 900500, type = 105, teacheid = 0, name = "1-6", cname = "包圍圈", plot_first = "Huo@dongPlot/XueXiao/xue_6", plot_last = "0", map = "0", bgm = "50-snowbattle", unlock = "1_910004", front = "900505", open = "900507_900500", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "翌日淩晨，大雪終於停下，天空露出了原本的藍色。但沒人因此感到高興，因為通過偵查這裏已經被原罪包圍。僅憑四位駕駛員或許可以解決雪地中密密麻麻的低等原罪，但絕對對抗不了准罪級……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900507] = {id = 900507, scroll = 900500, type = 105, teacheid = 0, name = "1-7", cname = "隱瞞", plot_first = "Huo@dongPlot/XueXiao/xue_7", plot_last = "0", map = "0", bgm = "50-snowbattle", unlock = "1_910004", front = "900506", open = "900508_900500", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在安置完普通居民們後，莫莫卡突然意識到了莉迪婭計畫的不對勁。莉迪婭或許想要犧牲自己來獲取其他幾人的安全撤離。在生死存亡之際，莉法卻提出了一個驚世駭俗的計畫……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_7", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900508] = {id = 900508, scroll = 900500, type = 108, teacheid = 0, name = "1-8", cname = "“災難”", plot_first = "Huo@dongPlot/XueXiao/xue_8", plot_last = "Huo@dongPlot/XueXiao/xue_8e", map = "xuedi", bgm = "51-underthesnow", unlock = "1_910004", front = "900507", open = "0", player = "13005_6_75_1_5_0_1_0_0_0_0_0_0_0;13014_6_75_1_5_0_1_0_0_0_0_0_0_0;11007_6_75_1_5_0_1_0_0_0_0_0_0_0;10018_6_75_1_5_0_1_0_0_0_0_0_0_0;10000_6_75_1_5_0_1_0_0_0_0_0_0_0;10001_6_75_1_5_0_1_0_0_0_0_0_0_0;11028_6_75_1_5_0_1_0_0_0_0_0_0_0;11029_6_75_1_5_0_1_0_0_0_0_0_0_0;10005_6_75_1_5_0_1_0_0_0_0_0_0_0", monster = "600014_3_1_0_1_8_1_0_0_0_0_100255_0_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_666_34,0_9_33", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "莉迪婭在熱尼亞的手心中醒來，卻找不到莫莫卡和莉法的身影。就在她詢問熱尼亞發生了什麼的時候，一場“災難”從遠處的岩石山壁中升起……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_8", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
