[900534] = {id = 900534, scroll = 900502, type = 103, teacheid = 0, name = "3-5", cname = "【瓦絲卡】討伐戰·困難", plot_first = "0", plot_last = "0", map = "xuedi", bgm = "51-underthesnow", unlock = "1_910005", front = "900533", open = "0", player = "0", monster = "600014_5_90_1_6_8_1_0_100155_6500_0_100355_10000_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_35_10,0_1_2", reward = "1_100000_50,1_100001_5000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "4月30日下午2點58分48秒，在謎之聲的幫助下，DOMINATOR成功發射……人類終於迎來了漫長的戰爭的勝利，但是為什麼！！……為什麼逆轉錄光線射偏了？！第一發光束，僅僅只摧毀了逆愛身邊的一扇【門】", prohibit = "220307;210806;211603;211604;202101;200800;200801;210200;211707;221000;221001", scrollmappos = "0", prohibitskill = "220307;210806;211603;211604;202101;200800;200801;210200;211707;221000;221001", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900535] = {id = 900535, scroll = 900500, type = 999, teacheid = 0, name = "1", cname = "救援信號", plot_first = "Huo@dongPlot/XueXiao/xue_1", plot_last = "Huo@dongPlot/XueXiao/xue_1e", map = "xuedi_yewan", bgm = "50-snowbattle", unlock = "0,1", front = "0", open = "900536_900500", player = "13005_3_50_0_5_0_1_0_0_0_0_0_0_0;13014_3_50_0_5_0_1_0_0_0_0_0_0_0;11007_3_50_0_5_0_1_0_0_0_0_0_0_0", monster = "220015_3_30_0_5_12_1_0_100031_3300_0_100031_2700_0;210010_3_30_0_3_6_1_0_100031_3300_0_100031_2700_0;220009_2_34_0_3_16_1_0_100031_3300_0_100031_2700_0", consume = "4_100001_0", frequency = 0, condition = "2_70_34,2_80_34,2_90_34", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "接收到斷斷續續的救援信號，雪鸮小隊頂著十年難遇的暴風雪前往調查。可是在前往信號來源處的路途中遭受了不明敵人的攻擊。大雪遮蔽了敵人的一切，唯一可以確定的是，敵人是個原罪……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900536] = {id = 900536, scroll = 900500, type = 2, teacheid = 0, name = "2", cname = "意外情況", plot_first = "Huo@dongPlot/XueXiao/xue_2", plot_last = "0", map = "0", bgm = "50-snowbattle", unlock = "0,1", front = "900535", open = "900537_900500", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在莉迪婭的掩護斷後下，熱尼亞與莫莫卡順利找到了發出救援信號的位置，而信號的發出者竟是瓦爾基裏小隊的隊員莉法。但出乎二人意料的是，這裏除了莉法之外還困著更多人……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900537] = {id = 900537, scroll = 900500, type = 2, teacheid = 0, name = "3", cname = "停電", plot_first = "Huo@dongPlot/XueXiao/xue_3", plot_last = "0", map = "0", bgm = "50-snowbattle", unlock = "0,1", front = "900536", open = "900538_900500", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "莉迪婭僥倖擺脫了原罪，拖著傷痕累累的身體撐到了冰炬基地，同事也帶來了有關原罪的些許資訊。就在幾人商討接下來如何行動之時，基地的能源卻出現了問題……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900538] = {id = 900538, scroll = 900500, type = 2, teacheid = 0, name = "4", cname = "基地深處", plot_first = "Huo@dongPlot/XueXiao/xue_4", plot_last = "0", map = "0", bgm = "50-snowbattle", unlock = "0,1", front = "900537", open = "900539_900500", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "三人輕鬆擊殺掉侵入的原罪，來到了基地的深處。展現在三人眼前的是一個時代的淚痕，一個曾經製造了歷史上最嚴重的人造災難的裝置——尼姆比斯電場發生器……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_4", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900539] = {id = 900539, scroll = 900500, type = 2, teacheid = 0, name = "5", cname = "另一方向", plot_first = "Huo@dongPlot/XueXiao/xue_5", plot_last = "0", map = "0", bgm = "50-snowbattle", unlock = "0,1", front = "900538", open = "900540_900500", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "通過損壞的門，三人發現了基地後方的出口。在離這不遠的地方就有一座樞紐城市……就在幾人商討下一步行動時，一種悄然的襲擊正在侵蝕熱尼亞的核心……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_5", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900540] = {id = 900540, scroll = 900500, type = 2, teacheid = 0, name = "6", cname = "包圍圈", plot_first = "Huo@dongPlot/XueXiao/xue_6", plot_last = "0", map = "0", bgm = "50-snowbattle", unlock = "0,1", front = "900539", open = "900541_900500", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "翌日淩晨，大雪終於停下，天空露出了原本的藍色。但沒人因此感到高興，因為通過偵查這裏已經被原罪包圍。僅憑四位駕駛員或許可以解決雪地中密密麻麻的低等原罪，但絕對對抗不了准罪級……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900541] = {id = 900541, scroll = 900500, type = 2, teacheid = 0, name = "7", cname = "隱瞞", plot_first = "Huo@dongPlot/XueXiao/xue_7", plot_last = "0", map = "0", bgm = "50-snowbattle", unlock = "0,1", front = "900540", open = "900542_900500", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在安置完普通居民們後，莫莫卡突然意識到了莉迪婭計畫的不對勁。莉迪婭或許想要犧牲自己來獲取其他幾人的安全撤離。在生死存亡之際，莉法卻提出了一個驚世駭俗的計畫……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_7", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900542] = {id = 900542, scroll = 900500, type = 998, teacheid = 0, name = "8", cname = "“災難”", plot_first = "Huo@dongPlot/XueXiao/xue_8", plot_last = "Huo@dongPlot/XueXiao/xue_8e", map = "xuedi", bgm = "51-underthesnow", unlock = "0,1", front = "900541", open = "900543_900501", player = "13005_6_75_1_5_0_1_0_0_0_0_0_0_0;13014_6_75_1_5_0_1_0_0_0_0_0_0_0;11007_6_75_1_5_0_1_0_0_0_0_0_0_0;10018_6_75_1_5_0_1_0_0_0_0_0_0_0;10000_6_75_1_5_0_1_0_0_0_0_0_0_0;10001_6_75_1_5_0_1_0_0_0_0_0_0_0;11028_6_75_1_5_0_1_0_0_0_0_0_0_0;11029_6_75_1_5_0_1_0_0_0_0_0_0_0;10005_6_75_1_5_0_1_0_0_0_0_0_0_0", monster = "600014_3_1_0_1_8_1_0_0_0_0_100255_0_0", consume = "4_100001_0", frequency = 0, condition = "2_70_34,2_80_34,2_90_34", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "莉迪婭在熱尼亞的手心中醒來，卻找不到莫莫卡和莉法的身影。就在她詢問熱尼亞發生了什麼的時候，一場“災難”從遠處的岩石山壁中升起……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_8", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900543] = {id = 900543, scroll = 900501, type = 15, teacheid = 0, name = "9", cname = "【瓦絲卡】討伐戰", plot_first = "0", plot_last = "0", map = "xuedi", bgm = "51-underthesnow", unlock = "0,1", front = "900542", open = "0", player = "0", monster = "600014_4_55_1_5_8_1_0_100155_3000_0_100355_3000_0", consume = "4_100001_16", frequency = 0, condition = "2_70_34,2_80_34,2_90_34", reward = "1_100000_10", drop = "0", victory = "4_200019_50,4_100000_160,1_100001_640", roleexp = "4_100002_160", failure = "4_100001_16", introduction = "0", prohibit = "220307;210806;211603;211604;202101;200800;200801;210200;211707;221000;221001", scrollmappos = "0", prohibitskill = "220307;210806;211603;211604;202101;200800;200801;210200;211707;221000;221001", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900601] = {id = 900601, scroll = 900600, type = 105, teacheid = 0, name = "1-1", cname = "時間之海", plot_first = "Huo@dongPlot/JingLuo/jingluo_01", plot_last = "0", map = "0", bgm = "20-Battle-Warehouse2_MP3", unlock = "1_910004", front = "0", open = "900602_900600", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "作為一支走出“搖籃”不久的新生隊伍，鯨落小隊正待一次磨合隊員關係以及實戰演習的機會，為此，艾吉斯特意為她們安排了一趟熱帶海濱之旅……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900602] = {id = 900602, scroll = 900600, type = 105, teacheid = 0, name = "1-2", cname = "冒險的起始", plot_first = "Huo@dongPlot/JingLuo/jingluo_02", plot_last = "0", map = "0", bgm = "20-Battle-Warehouse2_MP3", unlock = "1_910004", front = "900601", open = "900603_900600", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "對於冒險的渴望，驅使著妍妍蘿繼續對伽藍見死纏爛打，而在二人總算取得共識之際，鯨落隊長海姬卻突然發來通訊，向她們告知了接下來的行動……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900603] = {id = 900603, scroll = 900600, type = 105, teacheid = 0, name = "1-3", cname = "幽靈信號", plot_first = "Huo@dongPlot/JingLuo/jingluo_03", plot_last = "0", map = "0", bgm = "20-Battle-Warehouse2_MP3", unlock = "1_910004", front = "900602", open = "900604_900600", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "神秘莫測的求救信號，將鯨落眾人引至大洋深處，被叢瑯當局稱為“禁域”的那片海域。面對疑似幽靈船的存在，少女們分別採取了不同的態度……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900604] = {id = 900604, scroll = 900600, type = 107, teacheid = 0, name = "1-4", cname = "彼岸歸航", plot_first = "Huo@dongPlot/JingLuo/jingluo_04", plot_last = "Huo@dongPlot/JingLuo/jingluo_04e", map = "haizhan_baitian", bgm = "20-Battle-Warehouse2_MP3", unlock = "1_910004", front = "900603", open = "900605_900600", player = "10007_5_75_0_5_0_1_0_0_0_0_0_0_0;12008_5_75_0_5_0_1_0_0_0_0_0_0_0;12011_5_75_0_5_0_1_0_0_0_0_0_0_0;11024_5_75_0_5_0_1_0_0_0_0_0_0_0", monster = "600015_1_1_0_1_8_1_0_0_0_0_100255_0_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_666_34,0_9_33", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "半世紀前就已沉沒的戰列艦，由叢瑯市海上搜救隊隊長，說出了它那幾乎被人遺忘的名字——“上龍號”。就在人們察覺到上龍號的異常時，它卻突然鳴響了一聲汽笛……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_4", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900605] = {id = 900605, scroll = 900600, type = 107, teacheid = 0, name = "1-5", cname = "沉沒的過往", plot_first = "Huo@dongPlot/JingLuo/jingluo_05", plot_last = "Huo@dongPlot/JingLuo/jingluo_05e", map = "haizhan_baitian", bgm = "20-Battle-Warehouse2_MP3", unlock = "1_910004", front = "900604", open = "900606_900600", player = "10007_5_75_0_5_0_1_0_0_0_0_0_0_0;12008_5_75_0_5_0_1_0_0_0_0_0_0_0;12011_5_75_0_5_0_1_0_0_0_0_0_0_0;11024_5_75_0_5_0_1_0_0_0_0_0_0_0", monster = "600015_2_5_0_1_8_1_0_0_0_0_100255_0_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_666_34,0_9_33", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "與寄宿於上龍號的原罪交戰過後，鯨落等人選擇撤離了戰場。從白隊口中，她們得知了有關叢瑯市過去的繁華與失落，以及五十六年前的連續沉船事件……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_5", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900606] = {id = 900606, scroll = 900600, type = 105, teacheid = 0, name = "1-6", cname = "新的航路", plot_first = "Huo@dongPlot/JingLuo/jingluo_06", plot_last = "0", map = "0", bgm = "20-Battle-Warehouse2_MP3", unlock = "1_910004", front = "900605", open = "900607_900600", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "為了拖住朝叢瑯駛去的蘭提戈斯，眾人不得已選擇了分頭行動。而在這同一片天空之下、在彼此相連的大海之間，她們於各自的戰場找到了新的航路……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900607] = {id = 900607, scroll = 900600, type = 108, teacheid = 0, name = "1-7", cname = "“鯨落”", plot_first = "Huo@dongPlot/JingLuo/jingluo_07", plot_last = "Huo@dongPlot/JingLuo/jingluo_07e", map = "haizhan_baitian", bgm = "20-Battle-Warehouse2_MP3", unlock = "1_910004", front = "900606", open = "900608_900600", player = "10007_5_75_0_5_0_1_0_0_0_0_0_0_0;12008_5_75_0_5_0_1_0_0_0_0_0_0_0;12011_5_75_0_5_0_1_0_0_0_0_0_0_0;11024_5_75_0_5_0_1_0_0_0_0_0_0_0", monster = "600015_3_12_0_1_8_1_0_0_0_0_100255_0_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_666_34,0_9_33", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "隨著時間推移，蘭提戈斯愈發堅不可摧，唯有最為熟悉上龍號結構的白隊能夠提供戰勝它的辦法。惡戰之中，這頭舊時代的鋼鐵巨鯨將要發揮它最後的作用……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_7", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900608] = {id = 900608, scroll = 900600, type = 105, teacheid = 0, name = "1-8", cname = "再啟航", plot_first = "Huo@dongPlot/JingLuo/jingluo_08", plot_last = "0", map = "0", bgm = "52-shipbattle", unlock = "1_910004", front = "900607", open = "0", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在陽光無法觸及的深海，沉睡著珊瑚與叢瑯市的舊夢，五十六年前那場悲劇的殘響隨著海浪拍上沙灘，潮水牽引著小小的紙船再度啟航……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_8", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
