[900635] = {id = 900635, scroll = 900600, type = 2, teacheid = 0, name = "1", cname = "時間之海", plot_first = "Huo@dongPlot/JingLuo/jingluo_01", plot_last = "0", map = "0", bgm = "20-Battle-Warehouse2_MP3", unlock = "0,1", front = "0", open = "900636_900600", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "作為一支走出“搖籃”不久的新生隊伍，鯨落小隊正待一次磨合隊員關係以及實戰演習的機會，為此，艾吉斯特意為她們安排了一趟熱帶海濱之旅……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900636] = {id = 900636, scroll = 900600, type = 2, teacheid = 0, name = "2", cname = "冒險的起始", plot_first = "Huo@dongPlot/JingLuo/jingluo_02", plot_last = "0", map = "0", bgm = "20-Battle-Warehouse2_MP3", unlock = "0,1", front = "900635", open = "900637_900600", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "對於冒險的渴望，驅使著妍妍蘿繼續對伽藍見死纏爛打，而在二人總算取得共識之際，鯨落隊長海姬卻突然發來通訊，向她們告知了接下來的行動……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900637] = {id = 900637, scroll = 900600, type = 2, teacheid = 0, name = "3", cname = "幽靈信號", plot_first = "Huo@dongPlot/JingLuo/jingluo_03", plot_last = "0", map = "0", bgm = "20-Battle-Warehouse2_MP3", unlock = "0,1", front = "900636", open = "900638_900600", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "神秘莫測的求救信號，將鯨落眾人引至大洋深處，被叢瑯當局稱為“禁域”的那片海域。面對疑似幽靈船的存在，少女們分別採取了不同的態度……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900638] = {id = 900638, scroll = 900600, type = 998, teacheid = 0, name = "4", cname = "彼岸歸航", plot_first = "Huo@dongPlot/JingLuo/jingluo_04", plot_last = "Huo@dongPlot/JingLuo/jingluo_04e", map = "haizhan_baitian", bgm = "20-Battle-Warehouse2_MP3", unlock = "0,1", front = "900637", open = "900639_900600", player = "10007_5_75_0_5_0_1_0_0_0_0_0_0_0;12008_5_75_0_5_0_1_0_0_0_0_0_0_0;12011_5_75_0_5_0_1_0_0_0_0_0_0_0;11024_5_75_0_5_0_1_0_0_0_0_0_0_0", monster = "600015_1_1_0_1_8_1_0_0_0_0_100255_0_0", consume = "4_100001_0", frequency = 0, condition = "2_70_34,2_80_34,2_90_34", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "半世紀前就已沉沒的戰列艦，由叢瑯市海上搜救隊隊長，說出了它那幾乎被人遺忘的名字——“上龍號”。就在人們察覺到上龍號的異常時，它卻突然鳴響了一聲汽笛……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_4", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900639] = {id = 900639, scroll = 900600, type = 998, teacheid = 0, name = "5", cname = "沉沒的過往", plot_first = "Huo@dongPlot/JingLuo/jingluo_05", plot_last = "Huo@dongPlot/JingLuo/jingluo_05e", map = "haizhan_baitian", bgm = "20-Battle-Warehouse2_MP3", unlock = "0,1", front = "900638", open = "900640_900600", player = "10007_5_75_0_5_0_1_0_0_0_0_0_0_0;12008_5_75_0_5_0_1_0_0_0_0_0_0_0;12011_5_75_0_5_0_1_0_0_0_0_0_0_0;11024_5_75_0_5_0_1_0_0_0_0_0_0_0", monster = "600015_2_5_0_1_8_1_0_0_0_0_100255_0_0", consume = "4_100001_0", frequency = 0, condition = "2_70_34,2_80_34,2_90_34", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "與寄宿於上龍號的原罪交戰過後，鯨落等人選擇撤離了戰場。從白隊口中，她們得知了有關叢瑯市過去的繁華與失落，以及五十六年前的連續沉船事件……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_5", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900640] = {id = 900640, scroll = 900600, type = 2, teacheid = 0, name = "6", cname = "新的航路", plot_first = "Huo@dongPlot/JingLuo/jingluo_06", plot_last = "0", map = "0", bgm = "20-Battle-Warehouse2_MP3", unlock = "0,1", front = "900639", open = "900641_900600", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "為了拖住朝叢瑯駛去的蘭提戈斯，眾人不得已選擇了分頭行動。而在這同一片天空之下、在彼此相連的大海之間，她們於各自的戰場找到了新的航路……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900641] = {id = 900641, scroll = 900600, type = 998, teacheid = 0, name = "7", cname = "“鯨落”", plot_first = "Huo@dongPlot/JingLuo/jingluo_07", plot_last = "Huo@dongPlot/JingLuo/jingluo_07e", map = "haizhan_baitian", bgm = "20-Battle-Warehouse2_MP3", unlock = "0,1", front = "900640", open = "900642_900600", player = "10007_5_75_0_5_0_1_0_0_0_0_0_0_0;12008_5_75_0_5_0_1_0_0_0_0_0_0_0;12011_5_75_0_5_0_1_0_0_0_0_0_0_0;11024_5_75_0_5_0_1_0_0_0_0_0_0_0", monster = "600015_3_12_0_1_8_1_0_0_0_0_100255_0_0", consume = "4_100001_0", frequency = 0, condition = "2_70_34,2_80_34,2_90_34", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "隨著時間推移，蘭提戈斯愈發堅不可摧，唯有最為熟悉上龍號結構的白隊能夠提供戰勝它的辦法。惡戰之中，這頭舊時代的鋼鐵巨鯨將要發揮它最後的作用……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_7", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900642] = {id = 900642, scroll = 900600, type = 2, teacheid = 0, name = "8", cname = "再啟航", plot_first = "Huo@dongPlot/JingLuo/jingluo_08", plot_last = "0", map = "0", bgm = "52-shipbattle", unlock = "0,1", front = "900641", open = "900643_900601", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在陽光無法觸及的深海，沉睡著珊瑚與叢瑯市的舊夢，五十六年前那場悲劇的殘響隨著海浪拍上沙灘，潮水牽引著小小的紙船再度啟航……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_8", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
