[900477] = {id = 900477, scroll = 900407, type = 2, teacheid = 0, name = "3", cname = "人類原罪", plot_first = "Huo@dongPlot/XingXingYueJi/XS_2_2", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900476", open = "900478_900407", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "另一邊，領航和千秋遵從史蒂芬妮的吩咐來洛根市等待一位神秘駕駛員，但是在途中發現了一名人類身上帶著原罪的氣息 。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
