[900479] = {id = 900479, scroll = 900407, type = 2, teacheid = 0, name = "5", cname = "裂痕", plot_first = "Huo@dongPlot/XingXingYueJi/XS_4", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900478", open = "900480_900407", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "萊薇背過身，褪去自己的上衣。那是一道裂痕，一道將她和正常人的人生劃分開來的裂痕。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900480] = {id = 900480, scroll = 900407, type = 2, teacheid = 0, name = "6", cname = "“再生計畫”", plot_first = "Huo@dongPlot/XingXingYueJi/XS_5", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900479", open = "900481_900407", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“再生計畫”試圖削減人體對尼姆比斯能的排異性，增強人體的適應性，最終用尼姆比斯能來取代人體的細胞組織……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900481] = {id = 900481, scroll = 900407, type = 2, teacheid = 0, name = "7", cname = "約瑟芬·貝爾娜茨卡婭", plot_first = "Huo@dongPlot/XingXingYueJi/XS_6", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900480", open = "900482_900407", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "一直以來照顧著萊薇與黎貝卡的是，確實“再生計畫”的主導者，十年來，她一直在償還著過去的罪孽。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900482] = {id = 900482, scroll = 900407, type = 2, teacheid = 0, name = "8", cname = "掃墓", plot_first = "Huo@dongPlot/XingXingYueJi/XS_7", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900481", open = "900483_900407", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "洛根市最近忽然出現的原罪入侵和黎貝卡聽到的聲音，這兩件事絕不是巧合，領航決定找本地人星爍詢問“十二年前的大傢伙”的情報。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900483] = {id = 900483, scroll = 900407, type = 2, teacheid = 0, name = "9", cname = "間接接吻", plot_first = "Huo@dongPlot/XingXingYueJi/XS_8", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900482", open = "900484_900407", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "如果十二年裡沒有漏掉的原罪災害，我只能認為黎貝卡聽到的聲音，是十二年前留下來的原罪發出的聲音……你不在意間接接吻嗎？", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900484] = {id = 900484, scroll = 900407, type = 2, teacheid = 0, name = "10", cname = "原罪呼喚", plot_first = "Huo@dongPlot/XingXingYueJi/XS_9", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900483", open = "900485_900407", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“而它在呼喚的同伴……是我。”黎貝卡解讀出了原罪聲音蘊含的情緒，那是呼喚同伴的聲音，與此同時，原罪再一次入侵出現。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900485] = {id = 900485, scroll = 900407, type = 2, teacheid = 0, name = "11", cname = "友好交流", plot_first = "Huo@dongPlot/XingXingYueJi/XS_10", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900484", open = "900486_900407", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“你能理解嗎？現在有一顆能夠足以摧毀洛根市的定時炸彈，而它的開關就在我身上。”果然約瑟芬是這件事情的幕後黑手，但是她似乎有話要和我們說。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900486] = {id = 900486, scroll = 900407, type = 2, teacheid = 0, name = "12", cname = "為什麼是遊樂園", plot_first = "Huo@dongPlot/XingXingYueJi/XS_11", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900485", open = "900487_900407", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“就是要一開始把你們的情緒調動起來，你們才能好好享受今天，這個下午才會過得更有意義。”遊樂園比想像中有意思一些。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900487] = {id = 900487, scroll = 900407, type = 2, teacheid = 0, name = "13", cname = "預備領航", plot_first = "Huo@dongPlot/XingXingYueJi/XS_12", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900486", open = "900488_900407", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "拯救這座城市的辦法就是要犧牲黎貝卡，約瑟芬·貝爾娜茨卡婭，你知道自己在說些什麼嗎？這對姐妹對你來說算什麼？", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900488] = {id = 900488, scroll = 900407, type = 2, teacheid = 0, name = "14", cname = "“安心”之死", plot_first = "Huo@dongPlot/XingXingYueJi/XS_13", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900487", open = "900489_900407", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "自欺欺人的死，自我感動的死，與自己的獨特和解的死，被欺騙的死，愚者之死，黎貝卡。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900489] = {id = 900489, scroll = 900407, type = 2, teacheid = 0, name = "15", cname = "缺陷幻化", plot_first = "Huo@dongPlot/XingXingYueJi/XS_13e", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900488", open = "900490_900407", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "星爍又一次進行了巨大化，但是這種幻化方式只能維持五到十分鐘，她決定在脫離危險之前不斷地幻化來拯救大家，", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900490] = {id = 900490, scroll = 900407, type = 2, teacheid = 0, name = "16", cname = "星爍-1", plot_first = "Huo@dongPlot/XingXingYueJi/XS_14", plot_last = "0", map = "0", bgm = "35-Hazy", unlock = "0,1", front = "900489", open = "900491_900407", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "黎貝卡變成了巨大的貓型原罪，因為恐高而抗拒巨大化的千秋決定加入戰鬥，在救援的駕駛員趕來之前，這場戰鬥將繼續下去。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
