[900492] = {id = 900492, scroll = 900407, type = 999, teacheid = 0, name = "18", cname = "sister拯救行動", plot_first = "Huo@dongPlot/XingXingYueJi/XS_15", plot_last = "Huo@dongPlot/XingXingYueJi/XS_15e", map = "jichang_yewan", bgm = "44-starry", unlock = "0,1", front = "900491", open = "900493_900407", player = "10029_6_75_1_5_0_1_0_0_0_0_0_0_0;11031_6_75_1_5_0_1_0_0_0_0_0_0_0;11032_6_75_1_5_0_1_0_0_0_0_0_0_0;11033_6_75_1_5_0_1_0_0_0_0_0_0_0", monster = "230002_2_46_0_3_9_1_0_100030_3300_0_100230_1500_0;210006_2_41_0_3_15_1_0_100030_3300_0_100030_1500_0;200001_2_46_0_3_8_1_0_100030_3300_0_100230_1500_0;200015_3_37_0_3_11_1_0_100030_3300_0_100230_1500_0;230002_2_46_0_3_6_1_0_100030_3300_0_100230_1500_0;210016_3_37_0_3_13_1_0_100030_3300_0_100230_1500_0;210006_2_41_0_3_18_1_0_100030_3300_0_100030_1500_0;220013_2_41_0_3_4_1_0_100030_3300_0_100230_1500_0;200001_2_46_0_3_3_1_0_100030_3300_0_100230_1500_0", consume = "4_100001_0", frequency = 0, condition = "2_70_34,2_80_34,2_90_34", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "用尼姆比斯能取代人體組織，“再生計畫”殘次品萊薇，與某位預備領航開始了拯救sister的行動。並沒有人跟我說“要去拯救誰”、“幫助誰”，但是我從未對自己的行動產生過疑問，這是無關“拯救世界”的“英雄”之戰。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 75, bgpicture = "juqingtu_9", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
