[900714] = {id = 900714, scroll = 900702, type = 105, teacheid = 0, name = "3-5", cname = "遺囑派對", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_7", plot_last = "0", map = "0", bgm = "0", unlock = "1_910010", front = "900713", open = "900715_900702", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200021_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "九十九環拜託你把大家呼喚過來，打算從一次夜談中更深入地獲得未來的資訊——這是她預知未來的缺陷，需要通過情報來構建未來。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_7", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "21:00;九十九環的房間", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900715] = {id = 900715, scroll = 900702, type = 105, teacheid = 0, name = "3-6", cname = "“隊長”", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_8", plot_last = "0", map = "0", bgm = "0", unlock = "1_910010", front = "900714", open = "900716_900702", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200021_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "就和安潔莉卡隊長一樣，現第三研究室防衛班的隊長多洛莉絲，也做好了迎接自己死亡的心理準備。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_8", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "22:00;走廊", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900716] = {id = 900716, scroll = 900702, type = 105, teacheid = 0, name = "3-7", cname = "其二為天災", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_9", plot_last = "0", map = "0", bgm = "0", unlock = "1_910010", front = "900715", open = "900717_900702", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200021_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "九十九環繼續和你講述她所看到的，你所不知道的未來。在得到更多的情報後，她發現自己和你並未出現在這段未來中……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_9", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "22:00;走廊", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900717] = {id = 900717, scroll = 900702, type = 105, teacheid = 0, name = "3-8", cname = "“預知未來”", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_10", plot_last = "0", map = "0", bgm = "0", unlock = "1_910010", front = "900716", open = "9007032_900703", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200021_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "高等原罪貪婪開始了她的第二次行動，九十九環和史蒂芬妮就預知未來這個能力的缺陷開始了討論，史蒂芬妮認為九十九環的能力並不是預知未來而是觀測一條過去的世界線。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_10", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "23:00;指揮室", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
