[900722] = {id = 900722, scroll = 900704, type = 105, teacheid = 0, name = "5-3", cname = "【逆轉錄光束】", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_11e", plot_last = "0", map = "0", bgm = "0", unlock = "1_910010", front = "900721", open = "900723_900704", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200021_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "亞爾薇特和克莉絲蒂娜處理資料的時候發現了一組異常資料，這組異常資料揭示了【逆轉錄光束】的一角，亞爾薇特找到了“自殺”的契機，為了再次觀測到【逆轉錄光束】，她決定加入這次行動。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_12", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "24:00;實驗室", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900723] = {id = 900723, scroll = 900704, type = 105, teacheid = 0, name = "5-4", cname = "應死之人們", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_12", plot_last = "0", map = "0", bgm = "0", unlock = "1_910010", front = "900722", open = "900724_900704", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200021_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "紅博士，克莉絲蒂娜，亞爾薇特在給多洛莉絲的強化方案上起了分歧，亞爾薇特決定把自己最為重要的原型機託付多洛莉絲，克莉絲蒂娜看出了亞爾薇特在安排自己的遺產。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_13", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "1:00;實驗室", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900724] = {id = 900724, scroll = 900704, type = 105, teacheid = 0, name = "5-5", cname = "其三為訣別", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_13", plot_last = "0", map = "0", bgm = "0", unlock = "1_910010", front = "900723", open = "900725_900704", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200021_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "九十九環為了看到更清晰的未來，即使要承受莫大的痛苦也決定啟用維生艙，但是——她在未來看到自己死在了你的懷裡。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_14", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "24:00;史蒂芬妮的實驗室", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900725] = {id = 900725, scroll = 900704, type = 105, teacheid = 0, name = "5-6", cname = "獨屬於我的特典", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_14", plot_last = "0", map = "0", bgm = "0", unlock = "1_910010", front = "900724", open = "900726_900704", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200021_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "你找到了消沉的九十九環，你不知道她看到了什麼未來讓她受到了這麼大的打擊，但是這並不妨礙九十九環借你的膝蓋用一用。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_15", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "2:00;走廊", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
