[900801] = {id = 900801, scroll = 900800, type = 105, teacheid = 0, name = "1-1", cname = "重逢", plot_first = "Huo@dongPlot/ChenXi/cx_1", plot_last = "0", map = "0", bgm = "20-Battle-Warehouse2_MP3", unlock = "1_910004", front = "0", open = "900802_900800", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "從多瑙返回印加的駕駛員柯朗，在所長辦公室裏遇見了意料之外的老熟人。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900802] = {id = 900802, scroll = 900800, type = 105, teacheid = 0, name = "1-2", cname = "初見", plot_first = "Huo@dongPlot/ChenXi/cx_2", plot_last = "0", map = "0", bgm = "20-Battle-Warehouse2_MP3", unlock = "1_910004", front = "900801", open = "900803_900800", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "米拓三區，位於印加西北部的山脈區域，內有數座活火山。這裏不僅是兩人初次見面的地方，也是她們命運的轉折之地。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900803] = {id = 900803, scroll = 900800, type = 105, teacheid = 0, name = "1-3", cname = "研究所", plot_first = "Huo@dongPlot/ChenXi/cx_3", plot_last = "0", map = "0", bgm = "20-Battle-Warehouse2_MP3", unlock = "1_910004", front = "900802", open = "900804_900800", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "兩人開車前往研究所，發現那裏只有一片廢墟，與方才的城鎮沒什麼區別。經過調查，她們發現了可以通往地下的密道。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
