[900975] = {id = 900975, scroll = 900907, type = 2, teacheid = 0, name = "1", cname = "海蘿與流浪貓", plot_first = "Huo@dongPlot/XingWangTanZhao/xwtz_01", plot_last = "0", map = "0", bgm = "62-Chessington", unlock = "0,1", front = "0", open = "900976_900907", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "罗莎琳德与海萝在就“海萝能否收养流浪猫”这个问题讨论的时候，接到了战略部的消息……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900976] = {id = 900976, scroll = 900907, type = 2, teacheid = 0, name = "2", cname = "傳統負債者", plot_first = "Huo@dongPlot/XingWangTanZhao/xwtz_02", plot_last = "0", map = "0", bgm = "62-Chessington", unlock = "0,1", front = "900975", open = "900977_900907", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "赫莉，一位传统负债者，在今天过后将会完成身份上的大转变。这是能还清债务，通往幸福的钥匙，她将会成为一名预备驾驶员。在与店长耶德娜告别之后，她向方舟前进。在赫莉离去后，星烁拜访了耶德娜……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900977] = {id = 900977, scroll = 900907, type = 2, teacheid = 0, name = "3", cname = "你被開除了", plot_first = "Huo@dongPlot/XingWangTanZhao/xwtz_03", plot_last = "0", map = "0", bgm = "62-Chessington", unlock = "0,1", front = "900976", open = "900978_900907", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "海萝与罗莎琳德开始了幻化准备。与此同时赫莉也得知她被取消了预备驾驶员资格，在她与AI理论，情绪即将奔溃的时候，艾吉斯的AI先于她奔溃了——艾吉斯的安全系统被入侵了……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900978] = {id = 900978, scroll = 900907, type = 2, teacheid = 0, name = "4", cname = "逆風者", plot_first = "Huo@dongPlot/XingWangTanZhao/xwtz_04", plot_last = "0", map = "0", bgm = "62-Chessington", unlock = "0,1", front = "900977", open = "900979_900907", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "人类之敌原罪出现在了玛雅，此时逆着人潮走去的是——", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900979] = {id = 900979, scroll = 900907, type = 2, teacheid = 0, name = "5", cname = "死而復生", plot_first = "Huo@dongPlot/XingWangTanZhao/xwtz_05", plot_last = "0", map = "0", bgm = "62-Chessington", unlock = "0,1", front = "900978", open = "900980_900907", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "紧随着星烁赶到现场的是，海萝与罗莎琳德。三人合力击败了出现的原罪，但诡异的是——死去的原罪再一次复活了……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900980] = {id = 900980, scroll = 900907, type = 2, teacheid = 0, name = "6", cname = "被害者", plot_first = "Huo@dongPlot/XingWangTanZhao/xwtz_06", plot_last = "0", map = "0", bgm = "62-Chessington", unlock = "0,1", front = "900979", open = "900981_900907", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "死而复生的原罪被彻底击杀，星烁与前线小队告别之后从史蒂芬妮那里得知了玛雅支部长遇害的消息，而嫌疑人是与她有一面之缘的前玛雅支部预备驾驶员，赫莉·加西亚……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900981] = {id = 900981, scroll = 900907, type = 2, teacheid = 0, name = "7", cname = "辯護時間", plot_first = "Huo@dongPlot/XingWangTanZhao/xwtz_07", plot_last = "0", map = "0", bgm = "62-Chessington", unlock = "0,1", front = "900980", open = "900982_900907", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "嫌疑人赫莉·加西亚被艾吉斯的鹰犬洛基击毙——事情本该是这样发展的，但是星烁阻止了这一切，她认为罪犯另有其人……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900982] = {id = 900982, scroll = 900907, type = 2, teacheid = 0, name = "8", cname = "並不高貴的高貴者", plot_first = "Huo@dongPlot/XingWangTanZhao/xwtz_08", plot_last = "0", map = "0", bgm = "62-Chessington", unlock = "0,1", front = "900981", open = "900983_900907", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "自称贵族的大小姐遇上了并不高贵的高贵者，茫然的罗莎琳德暂时找到了自己的目标……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900983] = {id = 900983, scroll = 900907, type = 2, teacheid = 0, name = "9", cname = "最大受益者", plot_first = "Huo@dongPlot/XingWangTanZhao/xwtz_09", plot_last = "0", map = "0", bgm = "62-Chessington", unlock = "0,1", front = "900982", open = "900984_900907", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "南娜·斯塔达维，三十七岁，于2022年加入艾吉斯。将会是支部长死掉之后的最大受益者，也是星烁认定的最大的嫌疑人。秘密特工洛基调查到的暗杀名单也佐证了这一点……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900984] = {id = 900984, scroll = 900907, type = 2, teacheid = 0, name = "10", cname = "暗殺名單", plot_first = "Huo@dongPlot/XingWangTanZhao/xwtz_10", plot_last = "0", map = "0", bgm = "62-Chessington", unlock = "0,1", front = "900983", open = "900985_900907", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "遭受到袭击的三人撤离到了艾吉斯线人的安全屋中，也就是一直为身为童工的赫莉提供工作的耶德娜·海伦处，随后星烁在暗杀名单中找到了领航的名字……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900985] = {id = 900985, scroll = 900907, type = 2, teacheid = 0, name = "11", cname = "受刑人", plot_first = "Huo@dongPlot/XingWangTanZhao/xwtz_11", plot_last = "0", map = "0", bgm = "62-Chessington", unlock = "0,1", front = "900984", open = "900986_900907", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“受刑人”——顾名思义，就是一群过去犯下过重罪，如今正在以服役为赎罪方式的一群罪犯。即便同样是史蒂芬妮的棋子，洛基与星烁的命运也因为出身的不同而注定会不一样……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900986] = {id = 900986, scroll = 900907, type = 2, teacheid = 0, name = "12", cname = "無畏前線", plot_first = "Huo@dongPlot/XingWangTanZhao/xwtz_12", plot_last = "0", map = "0", bgm = "62-Chessington", unlock = "0,1", front = "900985", open = "900987_900907", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "精英驾驶员们去解决作为苍雾源头的准罪级原罪，而新人小队“前线”，则负责解决从苍雾中走出的原罪……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900987] = {id = 900987, scroll = 900907, type = 2, teacheid = 0, name = "13", cname = "全滅", plot_first = "Huo@dongPlot/XingWangTanZhao/xwtz_12e", plot_last = "0", map = "0", bgm = "62-Chessington", unlock = "0,1", front = "900986", open = "900988_900907", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“请接到讯息的驾驶员……通知支部，苍雾里有两只，或者更多——”伴随着通讯传递出的是——精英驾驶员的全灭……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900988] = {id = 900988, scroll = 900907, type = 2, teacheid = 0, name = "14", cname = "復仇者小隊", plot_first = "Huo@dongPlot/XingWangTanZhao/xwtz_13", plot_last = "0", map = "0", bgm = "62-Chessington", unlock = "0,1", front = "900987", open = "900989_900907", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“赫莉·加西亚”的人生只有一次，所以她要获得幸福，以这个身份，这个名字。抱持着这个念头，由赫莉，洛基与星烁构成的复仇者小队，开始了一场斩首行动……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900989] = {id = 900989, scroll = 900907, type = 2, teacheid = 0, name = "15", cname = "臨時兇手", plot_first = "Huo@dongPlot/XingWangTanZhao/xwtz_14", plot_last = "0", map = "0", bgm = "62-Chessington", unlock = "0,1", front = "900988", open = "900990_900907", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“我会成为杀死支部长，以及杀死临时支部长的杀人凶手，这就是我想到的办法，一个谁都不用为难的办法。”把一切的交给运气的星烁，见到了南娜……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900990] = {id = 900990, scroll = 900907, type = 2, teacheid = 0, name = "16", cname = "尼比魯", plot_first = "Huo@dongPlot/XingWangTanZhao/xwtz_15", plot_last = "0", map = "0", bgm = "62-Chessington", unlock = "0,1", front = "900989", open = "900991_900907", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "没有为精英驾驶员的死亡而遗憾的时间，罗莎琳德与海萝在决定坚守这里的时候就注定会遇上它——这场苍雾的源头，准罪级原罪尼比鲁……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900991] = {id = 900991, scroll = 900907, type = 2, teacheid = 0, name = "17", cname = "終焉來臨之時", plot_first = "Huo@dongPlot/XingWangTanZhao/xwtz_15e", plot_last = "0", map = "0", bgm = "62-Chessington", unlock = "0,1", front = "900990", open = "900992_900907", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "与其说是战斗，用单方面戏弄来形容这场战斗更贴切，尼比鲁在等待着某个时刻到来。随后在终焉来临之时，二人目睹了玛雅支部的毁灭……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900992] = {id = 900992, scroll = 900907, type = 2, teacheid = 0, name = "18", cname = "棋手", plot_first = "Huo@dongPlot/XingWangTanZhao/xwtz_16", plot_last = "0", map = "0", bgm = "62-Chessington", unlock = "0,1", front = "900991", open = "900993_900907", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“——史蒂芬妮，你所熟悉的历史，将不复存在。”名为南娜的人类，如同宣战般地说出了这句话，紧接着仿佛是为了这句话献上喝彩——玛雅方舟从正中间折为两半……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900993] = {id = 900993, scroll = 900907, type = 2, teacheid = 0, name = "19", cname = "駕駛員們", plot_first = "Huo@dongPlot/XingWangTanZhao/xwtz_17", plot_last = "0", map = "0", bgm = "62-Chessington", unlock = "0,1", front = "900992", open = "900994_900907", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "这是一场种族之间的灭绝战，踏上前来的是新人驾驶员小队“前线”的海萝与罗莎琳德，“不幸的好运者”星烁，“艾吉斯的走狗”洛基，以及“被开除的预备驾驶员”赫莉……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900994] = {id = 900994, scroll = 900907, type = 2, teacheid = 0, name = "20", cname = "星變OS", plot_first = "Huo@dongPlot/XingWangTanZhao/xwtz_18", plot_last = "0", map = "0", bgm = "62-Chessington", unlock = "0,1", front = "900993", open = "900995_900907", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "败北，败北，败北——即使不断地被击败，驾驶员们依旧前赴后继，直到再也站不起来为止，面对局势的失控，星烁决定动用她的秘密武器。为了能够击败怪物而成为怪物，这既是星变OS……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900995] = {id = 900995, scroll = 900907, type = 2, teacheid = 0, name = "21", cname = "一對一", plot_first = "Huo@dongPlot/XingWangTanZhao/xwtz_18e", plot_last = "0", map = "0", bgm = "62-Chessington", unlock = "0,1", front = "900994", open = "900996_900907", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "对付穷凶极恶的怪物，就需要化身为更强的怪物——为了赢下这场战斗，星烁逐步向无法回头的深渊滑落……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900996] = {id = 900996, scroll = 900907, type = 2, teacheid = 0, name = "22", cname = "黑雲", plot_first = "Huo@dongPlot/XingWangTanZhao/xwtz_19", plot_last = "0", map = "0", bgm = "62-Chessington", unlock = "0,1", front = "900995", open = "900997_900907", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“黑云”这是这次事件的幕后黑手，醒来的星烁记住了这个名字。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[900997] = {id = 900997, scroll = 900907, type = 15, teacheid = 0, name = "23", cname = "【埃柏爾】討伐戰", plot_first = "0", plot_last = "0", map = "qiesidun_posun", bgm = "61-ultimate-war", unlock = "0,1", front = "900996", open = "0", player = "0", monster = "600018_4_65_1_3_11_1_0_100155_5000_0_100355_7000_0", consume = "4_100001_16", frequency = 0, condition = "2_70_34,2_80_34,2_90_34", reward = "1_100000_10", drop = "0", victory = "4_200025_50,4_100000_160,1_100001_640", roleexp = "4_100002_160", failure = "4_100001_16", introduction = "0", prohibit = "220307;210806;200303;200304;201104;210306", scrollmappos = "0", prohibitskill = "220307;210806;200303;200304;201104;210306", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 65, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901001] = {id = 901001, scroll = 901000, type = 105, teacheid = 0, name = "1-1", cname = "噩夢時間part.1", plot_first = "Huo@dongPlot/QingRenJie/24qrj_1", plot_last = "0", map = "0", bgm = "64-memorize", unlock = "1_910004", front = "0", open = "901002_901000", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "莉莉絲的噩夢時間part.1", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901002] = {id = 901002, scroll = 901000, type = 105, teacheid = 0, name = "1-2", cname = "破例遲到", plot_first = "Huo@dongPlot/QingRenJie/24qrj_1e", plot_last = "0", map = "0", bgm = "64-memorize", unlock = "1_910004", front = "901001", open = "901003_901000", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "莉莉絲從未在約定好的日子遲到，除了這一次……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
