[901004] = {id = 901004, scroll = 901000, type = 105, teacheid = 0, name = "1-4", cname = "一見鐘情巧克力", plot_first = "Huo@dongPlot/QingRenJie/24qrj_2e", plot_last = "0", map = "0", bgm = "64-memorize", unlock = "1_910004", front = "901003", open = "901005_901000", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "難以置信，斯卡蒂把她的積蓄全部都揮霍了出去，為了取回被詐騙走的錢，莉莉絲行動了起來……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_4", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
