[901012] = {id = 901012, scroll = 901000, type = 105, teacheid = 0, name = "1-12", cname = "暗黑厨师长", plot_first = "Huo@dongPlot/QingRenJie/24qrj_8", plot_last = "0", map = "0", bgm = "64-memorize", unlock = "1_910004", front = "901011", open = "901013_901000", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "影之國女王斯卡蒂和多瑙一般市民查麗莎一起向暗黑厨师长莉莉絲學習製作巧克力的魔法。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901013] = {id = 901013, scroll = 901000, type = 105, teacheid = 0, name = "1-13", cname = "巧克力誤差學", plot_first = "Huo@dongPlot/QingRenJie/24qrj_8e", plot_last = "0", map = "0", bgm = "64-memorize", unlock = "1_910004", front = "901012", open = "901014_901000", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "巧克力考核時間到！嚴格的暗黑厨师长莉莉絲將親口品嘗學員們製作的巧克力，不及格的巧克力將被當場消滅。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901014] = {id = 901014, scroll = 901000, type = 105, teacheid = 0, name = "1-14", cname = "義理巧克力和我", plot_first = "Huo@dongPlot/QingRenJie/24qrj_9", plot_last = "0", map = "0", bgm = "64-memorize", unlock = "1_910004", front = "901013", open = "901015_901000", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_30,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "為了感謝領航的幫助，莉莉絲贈送了領航一份義理巧克力，沒想到她的偽通感忽然暴走——", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
