[901048] = {id = 901048, scroll = 901003, type = 2, teacheid = 0, name = "10", cname = "三位受害者", plot_first = "Huo@dongPlot/QingRenJie/24qrj_7", plot_last = "0", map = "0", bgm = "64-memorize", unlock = "0,1", front = "901047", open = "901049_901003", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "查麗莎在購買【一見鐘情巧克力】的時候遇見了有著同樣目標的斯卡蒂，在兩人僵持片刻時，莉莉絲姍姍來遲——", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901049] = {id = 901049, scroll = 901003, type = 2, teacheid = 0, name = "11", cname = "“公平交易”", plot_first = "Huo@dongPlot/QingRenJie/24qrj_7e", plot_last = "0", map = "0", bgm = "64-memorize", unlock = "0,1", front = "901048", open = "901050_901003", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“我帮助驾驶员们改变命运，她们为此付出盾币，这是公平交易我的朋友。”", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901050] = {id = 901050, scroll = 901003, type = 2, teacheid = 0, name = "12", cname = "暗黑厨师长", plot_first = "Huo@dongPlot/QingRenJie/24qrj_8", plot_last = "0", map = "0", bgm = "64-memorize", unlock = "0,1", front = "901049", open = "901051_901003", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "影之國女王斯卡蒂和多瑙一般市民查麗莎一起向暗黑厨师长莉莉絲學習製作巧克力的魔法。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901051] = {id = 901051, scroll = 901003, type = 2, teacheid = 0, name = "13", cname = "巧克力誤差學", plot_first = "Huo@dongPlot/QingRenJie/24qrj_8e", plot_last = "0", map = "0", bgm = "64-memorize", unlock = "0,1", front = "901050", open = "901052_901003", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "巧克力考核時間到！嚴格的暗黑厨师长莉莉絲將親口品嘗學員們製作的巧克力，不及格的巧克力將被當場消滅。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901052] = {id = 901052, scroll = 901003, type = 2, teacheid = 0, name = "14", cname = "義理巧克力和我", plot_first = "Huo@dongPlot/QingRenJie/24qrj_9", plot_last = "0", map = "0", bgm = "64-memorize", unlock = "0,1", front = "901051", open = "901053_901003", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "為了感謝領航的幫助，莉莉絲贈送了領航一份義理巧克力，沒想到她的偽通感忽然暴走——", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901053] = {id = 901053, scroll = 901003, type = 2, teacheid = 0, name = "15", cname = "第一次的家長會", plot_first = "Huo@dongPlot/QingRenJie/24qrj_9e", plot_last = "0", map = "0", bgm = "64-memorize", unlock = "0,1", front = "901052", open = "901054_901003", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "從摩根勒菲那裡得知，莉莉絲的通感暴走竟然是——神智的退化，即思維幼兒化。此時的你陷入了“如何教會莉莉絲穿衣服的困境”。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "juqingtu_6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
