[9011006] = {id = 9011006, scroll = 901112, type = 2, teacheid = 0, name = "04", cname = "一市之長", plot_first = "Huo@dongPlot/1ZhouNian/1ST_04", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "9011005", open = "9011007_901112", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "東西兩面皆調查無果，可即便是無價值的情報，也必須一一整理，上報市長。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
