[901365] = {id = 901365, scroll = 901306, type = 2, teacheid = 0, name = "1", cname = "早上好，世界", plot_first = "Huo@dongPlot/XiaHuo2/2024_XH2_01", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "0", open = "901366_901306", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "少女匍伏在你的身上，耳邊能聽到她平穩的呼吸聲，洗發露的甜味撲鼻而來。不管是從視覺上還是觸覺上的情報都印證著——這是一位赤裸的少女。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901366] = {id = 901366, scroll = 901306, type = 2, teacheid = 0, name = "2", cname = "女主角宇宙", plot_first = "Huo@dongPlot/XiaHuo2/2024_XH2_02", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901365", open = "901367_901306", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "女主角宇宙，顧名思義，是只有女主角存在的世界，而你作為唯一的男人亂入了這個宇宙……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901367] = {id = 901367, scroll = 901306, type = 2, teacheid = 0, name = "3", cname = "隱藏身份的重要性", plot_first = "Huo@dongPlot/XiaHuo2/2024_XH2_03", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901366", open = "901368_901306", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“如果不想被你的女主角們囚禁起來當寵物的話，就乖乖隱藏好身份。”撿到你的少女如是說道。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901368] = {id = 901368, scroll = 901306, type = 2, teacheid = 0, name = "4", cname = "像是友人的“某人”", plot_first = "Huo@dongPlot/XiaHuo2/2024_XH2_04", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901367", open = "901369_901306", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "你確信，現在一定是在做夢——要不然為什麼那個莉莉絲會用甜美的嗓音喊你“主人大人”。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_4", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901369] = {id = 901369, scroll = 901306, type = 2, teacheid = 0, name = "5", cname = "【光】", plot_first = "Huo@dongPlot/XiaHuo2/2024_XH2_05", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901368", open = "901370_901306", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "讓你沒想到的是，你的偽裝被莉莉絲一眼識破……最糟糕的是這件事已經引起了在餐廳就餐的伊莎貝拉等人的注意。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_5", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
