[901384] = {id = 901384, scroll = 901306, type = 0, teacheid = 0, name = "20", cname = "女主角", plot_first = "Huo@dongPlot/XiaHuo2/2024_XH2_19", plot_last = "Huo@dongPlot/XiaHuo2/2024_XH2_19e", map = "xiahuoyuzhou", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901383", open = "901385_901306", player = "0", monster = "230005_3_38_0_3_13_1_0_100030_3700_0_100231_1500_0;200000_2_43_0_3_2_1_0_100030_3700_0_100231_1500_0;230002_2_43_0_3_4_1_0_100030_3700_0_100231_1500_0;210010_2_47_0_3_11_1_0_100030_3700_0_100231_1500_0;230000_2_47_0_3_17_1_0_100030_3700_0_100231_1500_0;210010_2_47_0_3_12_1_0_100030_3700_0_100231_1500_0;230002_2_43_0_3_7_1_0_100030_3700_0_100231_1500_0;200000_2_47_0_3_15_1_0_100030_3700_0_100231_1500_0;230005_3_38_0_3_6_1_0_100030_3700_0_100231_1500_0", consume = "4_100001_0", frequency = 0, condition = "2_70_34,2_80_34,2_90_34", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“我的人生和你一點關係都沒有！聽到了嗎！我既不是你的女主角也不屬於這裏！即使如此……即便如此……我……我還是好想和你在一起啊……”", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_19", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
