[901400] = {id = 901400, scroll = 901400, type = 105, teacheid = 0, name = "1-1", cname = "超能力者們暢聊著過去", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_01", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910010", front = "0", open = "901401_901400,901409_901401", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200036_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "立直麻將中會輪流坐莊，但是代表莊家的標示從沒有離開過星爍的手邊。遊戲自東場零本場開始，在東場一本場結束。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901401] = {id = 901401, scroll = 901400, type = 105, teacheid = 0, name = "1-2", cname = "阿爾泰婭·維斯受難日", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_02", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910010", front = "901400", open = "901402_901400", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200036_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "少女這麼說著：“我不是較真，只是不喜歡用玩笑把事情敷衍過去。”", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901402] = {id = 901402, scroll = 901400, type = 105, teacheid = 0, name = "1-3", cname = "缸中之腦", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_03", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910010", front = "901401", open = "901403_901400", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200036_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "如果我們發現自己在過去的某一刻，或者說從生下來的時候就被取出大腦，裝在了某個裝置裡——塞繆，我們該怎麼做？", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901403] = {id = 901403, scroll = 901400, type = 105, teacheid = 0, name = "1-4", cname = "今 七實", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_04", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910010", front = "901402", open = "901404_901400", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200036_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "讀音是“Ima Nanami”，反過來讀也是“Ima Nanami”。若是論誰會願意出手幫小妹——那恐怕只有我今七實了。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_4", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901404] = {id = 901404, scroll = 901400, type = 105, teacheid = 0, name = "1-5", cname = "曾經我也是一名駕駛員", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_05", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910010", front = "901403", open = "901405_901400", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200036_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "如果要求每一個人都像她——多洛莉絲——不僅從絕望中振作起來，還成為了更好的自己，那無疑是一種強人所難。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_5", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901405] = {id = 901405, scroll = 901400, type = 105, teacheid = 0, name = "1-6", cname = "蜥蜴先生的假期", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_06", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910010", front = "901404", open = "901406_901400", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200036_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "科莫多巨蜥比一般的冷血動物都要好動且好鬥，所以它也叫鐵血的熱血的冷血的科莫多巨蜥。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901406] = {id = 901406, scroll = 901400, type = 105, teacheid = 0, name = "1-7", cname = "伊甸之蛇", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_07", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910010", front = "901405", open = "901407_901400", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200036_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "就這樣懷揣著對生活的無望，對未來的絕望，對人生的失望，一輩子痛苦而不幸地活下去吧，她咒罵自己。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_7", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
