[901422] = {id = 901422, scroll = 901402, type = 105, teacheid = 0, name = "3-1", cname = "假貨與真貨", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_10", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910011", front = "901408", open = "901423_901402,901435_901403", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200036_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "你們倆個人，只有一個人是真實的，而另一個人，是通過“通感”，欺瞞了所有人的感官，創造出來的“假貨”。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_10", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901423] = {id = 901423, scroll = 901402, type = 105, teacheid = 0, name = "3-2", cname = "邁著輕鬆的步伐介入", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_11", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910011", front = "901422", open = "901424_901402", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200036_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "想要幫助某個人，就是這樣簡單的理由——觸手可及的範圍，我從不視而不見。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_11", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901424] = {id = 901424, scroll = 901402, type = 105, teacheid = 0, name = "3-3", cname = "請告訴我吧，剎那大人", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_12", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910011", front = "901423", open = "901425_901402", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200036_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "比起原罪，我更加在意——七年前發生了什麼讓你這麼在意，希爾薇。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_12", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901425] = {id = 901425, scroll = 901402, type = 105, teacheid = 0, name = "3-4", cname = "無頭騎士與變態頭盔男", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_13", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910011", front = "901424", open = "901426_901402", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200036_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "瓦爾基裏的莉法小姐在我的印象中始終穿著那身女僕裝——她的言行舉止也十分符合大眾印象中的女僕，所以我一直認為莉法小姐是名女僕。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_13", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901426] = {id = 901426, scroll = 901402, type = 105, teacheid = 0, name = "3-5", cname = "菲琳，以駕駛員形態出擊", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_14", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910011", front = "901425", open = "901427_901402", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200036_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "如果你長大後的夢想是成為一名駕駛員的話，那我就要在你長大之前徹底殺死你的夢想。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_14", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901427] = {id = 901427, scroll = 901402, type = 105, teacheid = 0, name = "3-6", cname = "祝你早安，午安，以及晚安", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_15", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910011", front = "901426", open = "901428_901402", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200036_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "比起阿爾泰婭為了隱藏自己，製造了一個完全虛假的第二人塞繆——還是塞繆為了隱藏自己，創造了一個看起來完全是真實存在的阿爾泰婭更加符合直覺吧？", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_15", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901428] = {id = 901428, scroll = 901402, type = 105, teacheid = 0, name = "3-7", cname = "曾用名“塞繆”", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_16", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910011", front = "901427", open = "901429_901402", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200036_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "不要叫我塞繆，這個世界從來不存在“塞繆”，只有阿爾泰婭，阿爾泰婭·維斯。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_16", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901429] = {id = 901429, scroll = 901402, type = 108, teacheid = 0, name = "3-8", cname = "救世者們彙聚而來", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_17", plot_last = "Huo@dongPlot/MeiMengBuZai/mmbz_17e", map = "pulaiteshijiedao_yewan", bgm = "75-Who_am_I", unlock = "1_910011", front = "901428", open = "901430_901402", player = "11027_5_90_1_8_0_1_0_0_0_0_0_0_0;12025_5_90_1_8_0_1_0_0_0_0_0_0_0", monster = "600024_3_5_0_0_8_1_0_0_0_0_0_0_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_666_34,0_9_33", reward = "1_100000_10,1_100001_1000,4_200036_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "——閒話少說，接下來，享受獵殺吧。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_17", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901430] = {id = 901430, scroll = 901402, type = 105, teacheid = 0, name = "3-9", cname = "另類救世主", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_18", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910011", front = "901429", open = "901431_901402", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200036_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "尼姆比斯能源通常是無法在人體內儲存的，即使是巨大化的身軀，尼姆比斯能源也是以一個包裹住人體的狀態和人類共存。即便是偽通感者，也無法打破這個定論——人類的身體無法容納尼姆比斯能。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_18", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901431] = {id = 901431, scroll = 901402, type = 108, teacheid = 0, name = "3-10", cname = "向這個世界宣告", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_19", plot_last = "Huo@dongPlot/MeiMengBuZai/mmbz_19e", map = "pulaiteshijiedao_yewan", bgm = "75-Who_am_I", unlock = "1_910011", front = "901430", open = "901432_901402", player = "80001_6_100_1_8_0_1_0_0_0_0_0_0_0", monster = "600024_3_5_0_0_8_1_0_0_0_0_0_0_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_666_34,0_9_33", reward = "1_100000_10,1_100001_1000,4_200036_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "無論是壓迫感還是體型，都足以與耶夢加得媲美的原罪正在朝她逼近。九顆腦袋，共計十八只眼睛，從各自不同的角度注視著這名少女——蛇瞳裏面的少女，不管從哪個角度看，都看不出什麼奇特之處。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_19", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901432] = {id = 901432, scroll = 901402, type = 105, teacheid = 0, name = "3-11", cname = "法外狂徒", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_20", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910011", front = "901431", open = "901433_901402", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200036_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "我想知道七年前發生了什麼——是什麼毀了我，毀了我們，讓我們的人生變成現在這樣。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_20", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901433] = {id = 901433, scroll = 901402, type = 105, teacheid = 0, name = "3-12", cname = "美夢不再", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_21", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910011", front = "901432", open = "901434_901402", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200036_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "這起事件，絕不能算作是單方面的掠奪。是互相索取，是互相依賴。用美夢來逃避現實。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_21", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
