[901463] = {id = 901463, scroll = 901406, type = 2, teacheid = 0, name = "1", cname = "超能力者們暢聊著過去", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_01", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "0", open = "901464_901406", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "立直麻將中會輪流坐莊，但是代表莊家的標示從沒有離開過星爍的手邊。遊戲自東場零本場開始，在東場一本場結束。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901464] = {id = 901464, scroll = 901406, type = 2, teacheid = 0, name = "2", cname = "阿爾泰婭·維斯受難日", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_02", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "901463", open = "901465_901406", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "少女這麼說著：“我不是較真，只是不喜歡用玩笑把事情敷衍過去。”", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901465] = {id = 901465, scroll = 901406, type = 2, teacheid = 0, name = "3", cname = "缸中之腦", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_03", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "901464", open = "901466_901406", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "如果我們發現自己在過去的某一刻，或者說從生下來的時候就被取出大腦，裝在了某個裝置裡——塞繆，我們該怎麼做？", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901466] = {id = 901466, scroll = 901406, type = 2, teacheid = 0, name = "4", cname = "今 七實", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_04", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "901465", open = "901467_901406", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "讀音是“Ima Nanami”，反過來讀也是“Ima Nanami”。若是論誰會願意出手幫小妹——那恐怕只有我今七實了。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_4", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901467] = {id = 901467, scroll = 901406, type = 2, teacheid = 0, name = "5", cname = "曾經我也是一名駕駛員", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_05", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "901466", open = "901468_901406", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "如果要求每一個人都像她——多洛莉絲——不僅從絕望中振作起來，還成為了更好的自己，那無疑是一種強人所難。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_5", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901468] = {id = 901468, scroll = 901406, type = 2, teacheid = 0, name = "6", cname = "蜥蜴先生的假期", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_06", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "901467", open = "901469_901406", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "科莫多巨蜥比一般的冷血動物都要好動且好鬥，所以它也叫鐵血的熱血的冷血的科莫多巨蜥。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901469] = {id = 901469, scroll = 901406, type = 2, teacheid = 0, name = "7", cname = "伊甸之蛇", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_07", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "901468", open = "901470_901406", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "就這樣懷揣著對生活的無望，對未來的絕望，對人生的失望，一輩子痛苦而不幸地活下去吧，她咒罵自己。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_7", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901470] = {id = 901470, scroll = 901406, type = 2, teacheid = 0, name = "8", cname = "跟蹤狂們魚貫而入", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_08", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "901469", open = "901471_901406", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "我一路尾隨著機車服女性來到了此處，在進行了一番激烈的思想鬥爭後，我推開了別人的家門。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_8", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901471] = {id = 901471, scroll = 901406, type = 2, teacheid = 0, name = "9", cname = "塞繆", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_09", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "901470", open = "901472_901406", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "偽·通感者阿爾泰婭是真實存在的。而另一人——塞繆，是虛假的？", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_9", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901472] = {id = 901472, scroll = 901406, type = 2, teacheid = 0, name = "10", cname = "假貨與真貨", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_10", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "901471", open = "901473_901406", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "你們倆個人，只有一個人是真實的，而另一個人，是通過“通感”，欺瞞了所有人的感官，創造出來的“假貨”。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_10", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901473] = {id = 901473, scroll = 901406, type = 2, teacheid = 0, name = "11", cname = "邁著輕鬆的步伐介入", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_11", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "901472", open = "901474_901406", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "想要幫助某個人，就是這樣簡單的理由——觸手可及的範圍，我從不視而不見。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_11", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901474] = {id = 901474, scroll = 901406, type = 2, teacheid = 0, name = "12", cname = "請告訴我吧，剎那大人", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_12", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "901473", open = "901475_901406", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "比起原罪，我更加在意——七年前發生了什麼讓你這麼在意，希爾薇。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_12", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901475] = {id = 901475, scroll = 901406, type = 2, teacheid = 0, name = "13", cname = "無頭騎士與變態頭盔男", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_13", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "901474", open = "901476_901406", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "瓦爾基裏的莉法小姐在我的印象中始終穿著那身女僕裝——她的言行舉止也十分符合大眾印象中的女僕，所以我一直認為莉法小姐是名女僕。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_13", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901476] = {id = 901476, scroll = 901406, type = 2, teacheid = 0, name = "14", cname = "菲琳，以駕駛員形態出擊", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_14", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "901475", open = "901477_901406", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "如果你長大後的夢想是成為一名駕駛員的話，那我就要在你長大之前徹底殺死你的夢想。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_14", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901477] = {id = 901477, scroll = 901406, type = 2, teacheid = 0, name = "15", cname = "祝你早安，午安，以及晚安", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_15", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "901476", open = "901478_901406", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "比起阿爾泰婭為了隱藏自己，製造了一個完全虛假的第二人塞繆——還是塞繆為了隱藏自己，創造了一個看起來完全是真實存在的阿爾泰婭更加符合直覺吧？", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_15", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901478] = {id = 901478, scroll = 901406, type = 2, teacheid = 0, name = "16", cname = "曾用名“塞繆”", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_16", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "901477", open = "901479_901406", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "不要叫我塞繆，這個世界從來不存在“塞繆”，只有阿爾泰婭，阿爾泰婭·維斯。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_16", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901479] = {id = 901479, scroll = 901406, type = 998, teacheid = 0, name = "17", cname = "救世者們彙聚而來", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_17", plot_last = "Huo@dongPlot/MeiMengBuZai/mmbz_17e", map = "pulaiteshijiedao_yewan", bgm = "75-Who_am_I", unlock = "0,1", front = "901478", open = "901480_901406", player = "11027_5_90_1_8_0_1_0_0_0_0_0_0_0;12025_5_90_1_8_0_1_0_0_0_0_0_0_0", monster = "600024_3_5_0_0_8_1_0_0_0_0_0_0_0", consume = "4_100001_0", frequency = 0, condition = "2_70_34,2_80_34,2_90_34", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "——閒話少說，接下來，享受獵殺吧。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_17", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901480] = {id = 901480, scroll = 901406, type = 2, teacheid = 0, name = "18", cname = "另類救世主", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_18", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "901479", open = "901481_901406", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "尼姆比斯能源通常是無法在人體內儲存的，即使是巨大化的身軀，尼姆比斯能源也是以一個包裹住人體的狀態和人類共存。即便是偽通感者，也無法打破這個定論——人類的身體無法容納尼姆比斯能。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_18", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901481] = {id = 901481, scroll = 901406, type = 998, teacheid = 0, name = "19", cname = "向這個世界宣告", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_19", plot_last = "Huo@dongPlot/MeiMengBuZai/mmbz_19e", map = "pulaiteshijiedao_yewan", bgm = "75-Who_am_I", unlock = "0,1", front = "901480", open = "901482_901406", player = "80001_6_100_1_8_0_1_0_0_0_0_0_0_0", monster = "600024_3_5_0_0_8_1_0_0_0_0_0_0_0", consume = "4_100001_0", frequency = 0, condition = "2_70_34,2_80_34,2_90_34", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "無論是壓迫感還是體型，都足以與耶夢加得媲美的原罪正在朝她逼近。九顆腦袋，共計十八只眼睛，從各自不同的角度注視著這名少女——蛇瞳裏面的少女，不管從哪個角度看，都看不出什麼奇特之處。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_19", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901482] = {id = 901482, scroll = 901406, type = 2, teacheid = 0, name = "20", cname = "法外狂徒", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_20", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "901481", open = "901483_901406", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "我想知道七年前發生了什麼——是什麼毀了我，毀了我們，讓我們的人生變成現在這樣。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_20", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901483] = {id = 901483, scroll = 901406, type = 2, teacheid = 0, name = "21", cname = "美夢不再", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_21", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "901482", open = "901484_901406", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "這起事件，絕不能算作是單方面的掠奪。是互相索取，是互相依賴。用美夢來逃避現實。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_21", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901484] = {id = 901484, scroll = 901406, type = 2, teacheid = 0, name = "22", cname = "後日談", plot_first = "Huo@dongPlot/MeiMengBuZai/mmbz_22", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "901483", open = "901485_901406", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "故事來到了尾聲，而這場只有一個人會感到愉快的麻將對局也不可能再進行下去了。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_22", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
