[901500] = {id = 901500, scroll = 901500, type = 105, teacheid = 0, name = "1-1", cname = "陌生的熟人", plot_first = "Christmas2024/C1_1", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "1_910010", front = "0", open = "901501_901500,901510_901501", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200039_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在最溫馨的節日來到最寒冷的地區出差，前往的途中卻遇到了最陌生的熟人……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901501] = {id = 901501, scroll = 901500, type = 105, teacheid = 0, name = "1-2", cname = "冰湖旅館", plot_first = "Christmas2024/C1_2", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "1_910010", front = "901500", open = "901502_901500", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200039_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "廢棄的老舊旅館終於迎來了新的客人，從鋪在大廳的紅毯可以窺到這裏過去的輝煌……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901502] = {id = 901502, scroll = 901500, type = 105, teacheid = 0, name = "1-3", cname = "第一次", plot_first = "Christmas2024/C1_3", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "1_910010", front = "901501", open = "901503_901500", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200039_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "第一步找到一片厚實的冰面，確保冰下有著活水和魚群。第二步在冰上挖一個直徑約為20釐米的冰洞。第三步往洞內撒入一些餌料靜待一會兒後用下魚竿。第四步等待……無盡的等待……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901503] = {id = 901503, scroll = 901500, type = 105, teacheid = 0, name = "1-4", cname = "聖誕樹", plot_first = "Christmas2024/C1_4", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "1_910010", front = "901502", open = "901504_901500", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200039_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "聖誕樹，需要一顆挺拔的常青樹裝點上燈泡和聖誕裝飾品，是耶誕節必不可缺的一部分……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-4", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901504] = {id = 901504, scroll = 901500, type = 105, teacheid = 0, name = "1-5", cname = "“菈伊莎”", plot_first = "Christmas2024/C1_5", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "1_910010", front = "901503", open = "901505_901500", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200039_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“菈伊莎”一個代表無憂無慮的名字，正適合眼前懵懂而年幼的孩子，但是她體內存在的另一個聲音註定會讓這個美好祝願變成泡影……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-5", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901505] = {id = 901505, scroll = 901500, type = 105, teacheid = 0, name = "1-6", cname = "赫洛卡與秘密控制部", plot_first = "Christmas2024/C1_6", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "1_910010", front = "901504", open = "901506_901500", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200039_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在北極圈之北，寒冷之地的深處，正是第一研究室控制部的所在之處，而能夠掌控這裏的唯有赫洛卡一人……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901506] = {id = 901506, scroll = 901500, type = 105, teacheid = 0, name = "1-7", cname = "平安夜", plot_first = "Christmas2024/C1_7", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "1_910010", front = "901505", open = "901507_901500", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200039_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在平安夜的鐘聲響起之前，所有人都應該待在家中與親人和好友相聚。將此刻的美好記在心裏，然後用一生去回憶……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-7", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901507] = {id = 901507, scroll = 901500, type = 105, teacheid = 0, name = "1-8", cname = "車中夜談", plot_first = "Christmas2024/C1_8", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "1_910010", front = "901506", open = "901508_901500", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200039_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在卡佳的夜晚漫步或許會遇到夢遊的野獸，針鋒相對或者擦肩而過。槍可以驅趕現實中的動物，或許也能制止心中憤怒的野獸……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-8", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901508] = {id = 901508, scroll = 901500, type = 105, teacheid = 0, name = "1-9", cname = "GK計畫", plot_first = "Christmas2024/C1_9", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "1_910010", front = "901507", open = "901509_901500", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200039_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "GK計畫，一個針對高等原罪核心開發的嘗試性實驗專案，停滯不前許久的專案進度，將在今日以一種悲傷、焦慮、宏偉的形式，突破……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-9", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901509] = {id = 901509, scroll = 901500, type = 104, teacheid = 0, name = "1-10", cname = "重逢與新生", plot_first = "Christmas2024/C1_10", plot_last = "Christmas2024/C1_10e", map = "xuedixiugai", bgm = "17-Battle-jidu_MP3", unlock = "1_910010", front = "901508", open = "0", player = "0", monster = "600003_3_30_0_1_5_1_0_0_0_0_0_0_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_10,1_100001_1000,4_200039_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "高昂的叫聲在雪海之上迴響，從屍骸中醒來的巨鯨，舞動金屬巨鰭向著高空遊去。浮游空海的巨鯨，承載著三個人的固執和希望……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-10", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
