[901523] = {id = 901523, scroll = 901502, type = 105, teacheid = 0, name = "3-1", cname = "妄想性回憶", plot_first = "Christmas2024/C2_1", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "1_910011", front = "901509", open = "901524_901502,901535_901503", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200039_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在熟悉的車內醒來，看著似曾相識的場景，昨日的種種悲傷激動，似乎是一場不願記起的噩夢……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901524] = {id = 901524, scroll = 901502, type = 105, teacheid = 0, name = "3-2", cname = "重複迷失", plot_first = "Christmas2024/C2_2", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "1_910011", front = "901523", open = "901525_901502", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200039_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在熟悉的車內醒來，看著似曾相識的場景，昨日的種種悲傷激動，那絕對不只是一場夢……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901525] = {id = 901525, scroll = 901502, type = 105, teacheid = 0, name = "3-3", cname = "關鍵線索", plot_first = "Christmas2024/C2_3", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "1_910011", front = "901524", open = "901526_901502", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200039_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在熟悉的車內醒來，看著似曾相識的場景，記不得是第幾次睜開眼，或許這一次能夠找到離開這裏的線索……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901526] = {id = 901526, scroll = 901502, type = 105, teacheid = 0, name = "3-4", cname = "不同的“菈伊莎”", plot_first = "Christmas2024/C2_4", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "1_910011", front = "901525", open = "901527_901502", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200039_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "緊閉的門之後是血色的世界，眼前之人已經不再是記憶中的菈伊莎。來不及思考，子彈已經擊穿了此次迴圈……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-4", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901527] = {id = 901527, scroll = 901502, type = 105, teacheid = 0, name = "3-5", cname = "離別", plot_first = "Christmas2024/C2_5", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "1_910011", front = "901526", open = "901528_901502", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200039_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "短暫的重遇之後是永遠的離別……不，還有挽回的機會，在一切塵埃落定之前……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-5", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901528] = {id = 901528, scroll = 901502, type = 105, teacheid = 0, name = "3-6", cname = "【伊卡洛斯】", plot_first = "Christmas2024/C2_6", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "1_910011", front = "901527", open = "901529_901502", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200039_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "遊蕩在高空的驚駭巨獸，名為【伊卡洛斯】的巨大鯨魚。現在領航所想的竟然是要從在人類手中拯救原罪……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901529] = {id = 901529, scroll = 901502, type = 105, teacheid = 0, name = "3-7", cname = "人類的天使", plot_first = "Christmas2024/C2_7", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "1_910011", front = "901528", open = "901530_901502", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200039_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "為了拯救伊莉雅，為了接近【伊卡洛斯】，波琳娜毫無顧慮地踏上了通往天堂的臺階，在那裏她將化身天使，如同命中註定……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-7", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901530] = {id = 901530, scroll = 901502, type = 105, teacheid = 0, name = "3-8", cname = "拋竿", plot_first = "Christmas2024/C2_8", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "1_910011", front = "901529", open = "901531_901502", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200039_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "一切的準備就緒，目標是遠處天空遊蕩的巨鯨。而現在赫洛卡將拋出那決定性的一竿……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-8", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901531] = {id = 901531, scroll = 901502, type = 108, teacheid = 0, name = "3-9", cname = "“嫉妒”", plot_first = "Christmas2024/C2_9", plot_last = "Christmas2024/C2_9e", map = "Yunhai", bgm = "79-Stalemate", unlock = "1_910011", front = "901530", open = "901532_901502", player = "11050_6_100_1_9_0_1_0_0_0_0_0_0_0", monster = "600025_1_10_0_0_8_1_0_0_0_0_0_0_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_666_34,0_9_33", reward = "1_100000_10,1_100001_1000,4_200039_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "穿梭在【伊卡洛斯】的身體之中，尋找著那泛著藍色光芒的巨大水晶。沒想到在巨鯨的體內竟然還存在著一個巨大的少女，她的名字不是“伊莉雅”不是“菈伊莎”而是“嫉妒”……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 2, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-9", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901532] = {id = 901532, scroll = 901502, type = 105, teacheid = 0, name = "3-10", cname = "靈魂與記憶的區別", plot_first = "Christmas2024/C2_10", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "1_910011", front = "901531", open = "901333_901302", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200039_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在記憶世界的深處是由遺忘之物彙聚而成的海洋，菈伊莎將自己拋棄在這裏，作為靈魂來與記憶相制衡……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-10", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901533] = {id = 901533, scroll = 901502, type = 105, teacheid = 0, name = "3-11", cname = "不靠譜的聖誕老人", plot_first = "Christmas2024/C2_11", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "1_910011", front = "901532", open = "901334_901302", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200039_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "聖誕老人的雪橇在最巧合的時候來到了最巧合的地方，然而這畢竟不是聖誕老人的雪橇，坐在裏面的也不是個靠譜的聖誕老人……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-11", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901534] = {id = 901534, scroll = 901502, type = 105, teacheid = 0, name = "3-12", cname = "無夜可守", plot_first = "Christmas2024/C2_12", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "1_910011", front = "901533", open = "0", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200039_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "卡佳度過了一個危險的耶誕節，此次的危機也必須有人負起責任。追根溯源，赫洛卡好像就是此次危機的始作俑者，第一研究室控制部也將岌岌可危。難道自此之後守夜人將無夜可守？……或許並非如此。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-12", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
