[901563] = {id = 901563, scroll = 901506, type = 2, teacheid = 0, name = "1", cname = "陌生的熟人", plot_first = "Huo@dongPlot/Christmas2024/C1_1", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "0", open = "901564_901506", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在最溫馨的節日來到最寒冷的地區出差，前往的途中卻遇到了最陌生的熟人……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901564] = {id = 901564, scroll = 901506, type = 2, teacheid = 0, name = "2", cname = "冰湖旅館", plot_first = "Huo@dongPlot/Christmas2024/C1_2", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901563", open = "901565_901506", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "廢棄的老舊旅館終於迎來了新的客人，從鋪在大廳的紅毯可以窺到這裏過去的輝煌……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901565] = {id = 901565, scroll = 901506, type = 2, teacheid = 0, name = "3", cname = "第一次", plot_first = "Huo@dongPlot/Christmas2024/C1_3", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901564", open = "901566_901506", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "第一步找到一片厚實的冰面，確保冰下有著活水和魚群。第二步在冰上挖一個直徑約為20釐米的冰洞。第三步往洞內撒入一些餌料靜待一會兒後用下魚竿。第四步等待……無盡的等待……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901566] = {id = 901566, scroll = 901506, type = 2, teacheid = 0, name = "4", cname = "聖誕樹", plot_first = "Huo@dongPlot/Christmas2024/C1_4", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901565", open = "901567_901506", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "聖誕樹，需要一顆挺拔的常青樹裝點上燈泡和聖誕裝飾品，是耶誕節必不可缺的一部分……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-4", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901567] = {id = 901567, scroll = 901506, type = 2, teacheid = 0, name = "5", cname = "“菈伊莎”", plot_first = "Huo@dongPlot/Christmas2024/C1_5", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901566", open = "901568_901506", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“菈伊莎”一個代表無憂無慮的名字，正適合眼前懵懂而年幼的孩子，但是她體內存在的另一個聲音註定會讓這個美好祝願變成泡影……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-5", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901568] = {id = 901568, scroll = 901506, type = 2, teacheid = 0, name = "6", cname = "赫洛卡與秘密控制部", plot_first = "Huo@dongPlot/Christmas2024/C1_6", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901567", open = "901569_901506", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在北極圈之北，寒冷之地的深處，正是第一研究室控制部的所在之處，而能夠掌控這裏的唯有赫洛卡一人……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901569] = {id = 901569, scroll = 901506, type = 2, teacheid = 0, name = "7", cname = "平安夜", plot_first = "Huo@dongPlot/Christmas2024/C1_7", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901568", open = "901570_901506", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在平安夜的鐘聲響起之前，所有人都應該待在家中與親人和好友相聚。將此刻的美好記在心裏，然後用一生去回憶……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-7", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901570] = {id = 901570, scroll = 901506, type = 2, teacheid = 0, name = "8", cname = "車中夜談", plot_first = "Huo@dongPlot/Christmas2024/C1_8", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901569", open = "901571_901506", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在卡佳的夜晚漫步或許會遇到夢遊的野獸，針鋒相對或者擦肩而過。槍可以驅趕現實中的動物，或許也能制止心中憤怒的野獸……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-8", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901571] = {id = 901571, scroll = 901506, type = 2, teacheid = 0, name = "9", cname = "GK計畫", plot_first = "Huo@dongPlot/Christmas2024/C1_9", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901570", open = "901572_901506", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "GK計畫，一個針對高等原罪核心開發的嘗試性實驗專案，停滯不前許久的專案進度，將在今日以一種悲傷、焦慮、宏偉的形式，突破……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-9", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901572] = {id = 901572, scroll = 901506, type = 15, teacheid = 0, name = "10", cname = "重逢與新生", plot_first = "Huo@dongPlot/Christmas2024/C1_10", plot_last = "Huo@dongPlot/Christmas2024/C1_10e", map = "xuedixiugai", bgm = "17-Battle-jidu_MP3", unlock = "0,1", front = "901571", open = "901573_901506", player = "0", monster = "600003_3_30_0_1_5_1_0_0_0_0_0_0_0", consume = "4_100001_0", frequency = 0, condition = "2_70_34,2_80_34,2_90_34", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "高昂的叫聲在雪海之上迴響，從屍骸中醒來的巨鯨，舞動金屬巨鰭向著高空遊去。浮游空海的巨鯨，承載著三個人的固執和希望……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-10", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901573] = {id = 901573, scroll = 901506, type = 2, teacheid = 0, name = "11", cname = "妄想性回憶", plot_first = "Huo@dongPlot/Christmas2024/C2_1", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901572", open = "901574_901506", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在熟悉的車內醒來，看著似曾相識的場景，昨日的種種悲傷激動，似乎是一場不願記起的噩夢……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901574] = {id = 901574, scroll = 901506, type = 2, teacheid = 0, name = "12", cname = "重複迷失", plot_first = "Huo@dongPlot/Christmas2024/C2_2", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901573", open = "901575_901506", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在熟悉的車內醒來，看著似曾相識的場景，昨日的種種悲傷激動，那絕對不只是一場夢……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901575] = {id = 901575, scroll = 901506, type = 2, teacheid = 0, name = "13", cname = "關鍵線索", plot_first = "Huo@dongPlot/Christmas2024/C2_3", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901574", open = "901576_901506", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在熟悉的車內醒來，看著似曾相識的場景，記不得是第幾次睜開眼，或許這一次能夠找到離開這裏的線索……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901576] = {id = 901576, scroll = 901506, type = 2, teacheid = 0, name = "14", cname = "不同的“菈伊莎”", plot_first = "Huo@dongPlot/Christmas2024/C2_4", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901575", open = "901577_901506", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "緊閉的門之後是血色的世界，眼前之人已經不再是記憶中的菈伊莎。來不及思考，子彈已經擊穿了此次迴圈……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-4", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901577] = {id = 901577, scroll = 901506, type = 2, teacheid = 0, name = "15", cname = "離別", plot_first = "Huo@dongPlot/Christmas2024/C2_5", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901576", open = "901578_901506", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "短暫的重遇之後是永遠的離別……不，還有挽回的機會，在一切塵埃落定之前……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-5", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901578] = {id = 901578, scroll = 901506, type = 2, teacheid = 0, name = "16", cname = "【伊卡洛斯】", plot_first = "Huo@dongPlot/Christmas2024/C2_6", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901577", open = "901579_901506", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "遊蕩在高空的驚駭巨獸，名為【伊卡洛斯】的巨大鯨魚。現在領航所想的竟然是要從在人類手中拯救原罪……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901579] = {id = 901579, scroll = 901506, type = 2, teacheid = 0, name = "17", cname = "人類的天使", plot_first = "Huo@dongPlot/Christmas2024/C2_7", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901578", open = "901580_901506", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "為了拯救伊莉雅，為了接近【伊卡洛斯】，波琳娜毫無顧慮地踏上了通往天堂的臺階，在那裏她將化身天使，如同命中註定……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-7", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901580] = {id = 901580, scroll = 901506, type = 2, teacheid = 0, name = "18", cname = "拋竿", plot_first = "Huo@dongPlot/Christmas2024/C2_8", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901579", open = "901581_901506", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "一切的準備就緒，目標是遠處天空遊蕩的巨鯨。而現在赫洛卡將拋出那決定性的一竿……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-8", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901581] = {id = 901581, scroll = 901506, type = 998, teacheid = 0, name = "19", cname = "“嫉妒”", plot_first = "Huo@dongPlot/Christmas2024/C2_9", plot_last = "Huo@dongPlot/Christmas2024/C2_9e", map = "Yunhai", bgm = "79-Stalemate", unlock = "0,1", front = "901580", open = "901582_901506", player = "11050_6_100_1_9_0_1_0_0_0_0_0_0_0", monster = "600025_1_10_0_0_8_1_0_0_0_0_0_0_0", consume = "4_100001_0", frequency = 0, condition = "2_70_34,2_80_34,2_90_34", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "穿梭在【伊卡洛斯】的身體之中，尋找著那泛著藍色光芒的巨大水晶。沒想到在巨鯨的體內竟然還存在著一個巨大的少女，她的名字不是“伊莉雅”不是“菈伊莎”而是“嫉妒”……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 2, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-9", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901582] = {id = 901582, scroll = 901506, type = 2, teacheid = 0, name = "20", cname = "靈魂與記憶的區別", plot_first = "Huo@dongPlot/Christmas2024/C2_10", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901581", open = "901583_901506", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在記憶世界的深處是由遺忘之物彙聚而成的海洋，菈伊莎將自己拋棄在這裏，作為靈魂來與記憶相制衡……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-10", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901583] = {id = 901583, scroll = 901506, type = 2, teacheid = 0, name = "21", cname = "不靠譜的聖誕老人", plot_first = "Huo@dongPlot/Christmas2024/C2_11", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901582", open = "901584_901506", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "聖誕老人的雪橇在最巧合的時候來到了最巧合的地方，然而這畢竟不是聖誕老人的雪橇，坐在裏面的也不是個靠譜的聖誕老人……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-11", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901584] = {id = 901584, scroll = 901506, type = 2, teacheid = 0, name = "22", cname = "無夜可守", plot_first = "Huo@dongPlot/Christmas2024/C2_12", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "901583", open = "901585_901506", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "卡佳度過了一個危險的耶誕節，此次的危機也必須有人負起責任。追根溯源，赫洛卡好像就是此次危機的始作俑者，第一研究室控制部也將岌岌可危。難道自此之後守夜人將無夜可守？……或許並非如此。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-12", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
