[901600] = {id = 901600, scroll = 901600, type = 105, teacheid = 0, name = "1-1", cname = "領航的孩子", plot_first = "2025_qingrenjie/2025_qingrenjie_01", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "1_910010", front = "0", open = "901601_901600,901608_901601", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200043_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“因为人家有了他的孩子……现在得去找他商量之后该怎么办……”陌生的女孩子在尋找著領航，據她所說，她懷上了領航的孩子。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901601] = {id = 901601, scroll = 901600, type = 105, teacheid = 0, name = "1-2", cname = "超級戀愛偵探助手", plot_first = "2025_qingrenjie/2025_qingrenjie_02", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "1_910010", front = "901600", open = "901602_901600", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200043_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "在解決完關於“孩子”的問題後，未來終於想起了此行的目的——", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
