[901650] = {id = 901650, scroll = 901606, type = 2, teacheid = 0, name = "1-1", cname = "領航的孩子", plot_first = "Huo@dongPlot/QingRenJie2/2025_qingrenjie_01", plot_last = "0", map = "0", bgm = "21-Battle-Warehouse3_MP3", unlock = "0,1", front = "0", open = "901651_901606", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“因为人家有了他的孩子……现在得去找他商量之后该怎么办……”陌生的女孩子在尋找著領航，據她所說，她懷上了領航的孩子。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1-1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
