[901700] = {id = 901700, scroll = 901700, type = 105, teacheid = 0, name = "1-1", cname = "臨時撤退", plot_first = "2year/2year_01", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "1_910010", front = "0", open = "901701_901700,901711_901700", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200047_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "損失過半的駕駛員部隊，無法對被感染成原罪的人類駕駛員動手的幽靈部隊，以及暫時停止活動的原罪方舟……複雜的狀況使得我們暫時撤退。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1_2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901701] = {id = 901701, scroll = 901700, type = 105, teacheid = 0, name = "1-2", cname = "D型之死", plot_first = "2year/2year_02", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "1_910010", front = "901700", open = "901702_901700", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200047_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“所謂的擬態人格就是通過技術手段將某個活著的人格複寫進程序中，由此製造出的特殊晶片便被稱為“擬態人格”。”", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1_3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901702] = {id = 901702, scroll = 901700, type = 105, teacheid = 0, name = "1-3", cname = "女兒、女兒、以及兵器", plot_first = "2year/2year_00", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "1_910010", front = "901701", open = "901703_901700", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200047_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "奧德賽先生的女兒並不止一個……尼莫西妮，以及D型b2的人格數據來源……達芙妮。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901703] = {id = 901703, scroll = 901700, type = 105, teacheid = 0, name = "1-4", cname = "勇者與同伴一號", plot_first = "2year/2year_03", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "1_910010", front = "901702", open = "901704_901700", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200047_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "拯救世界之後，倖存的人類得給我打造一個三十米高的雕像，讚頌我，崇拜我，把我的故事永遠流傳下去。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1_4", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901704] = {id = 901704, scroll = 901700, type = 105, teacheid = 0, name = "1-5", cname = "世界毀滅之後", plot_first = "2year/2year_04", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "1_910010", front = "901703", open = "901705_901700", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200047_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "世界毀滅了——如同三流科幻小說裡的情節一樣，我來到了人類文明滅亡後的世界。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1_5", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901705] = {id = 901705, scroll = 901700, type = 104, teacheid = 0, name = "1-6", cname = "潘多拉引擎", plot_first = "2year/2year_05", plot_last = "0", map = "yueqiubiaomian", bgm = "40-Battle-Maya", unlock = "1_910010", front = "901704", open = "901706_901700", player = "0", monster = "200018_3_10_0_3_9_1_0_100030_3500_0_100230_1500_0;200018_3_10_0_3_15_1_0_100030_3500_0_100230_1500_0;200018_3_10_0_3_11_1_0_100030_3500_0_100230_1500_0;200018_3_10_0_3_7_1_0_100030_3500_0_100230_1500_0;200018_3_10_0_3_4_1_0_100030_3500_0_100230_1500_0;200018_3_10_0_3_18_1_0_100030_3500_0_100230_1500_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_10,1_100001_1000,4_200047_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "我是駕駛員，人類最後的駕駛員——斯珀絲。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1_6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901706] = {id = 901706, scroll = 901700, type = 105, teacheid = 0, name = "1-7", cname = "時間旅行者", plot_first = "2year/2year_06", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "1_910010", front = "901705", open = "901707_901700", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200047_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "我是勇者，只是撿到一個時間旅行者也沒什麼好大驚小怪的吧。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1_7", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901707] = {id = 901707, scroll = 901700, type = 105, teacheid = 0, name = "1-8", cname = "抱著貓的少女", plot_first = "2year/2year_07", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "1_910010", front = "901706", open = "901708_901700", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200047_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "我們在新切斯頓遇上的第一名居民，是位捧著貓咪的女孩。她正用打量某種少見外來生物（某種意義上沒錯）的目光上下掃視我。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1_8", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901708] = {id = 901708, scroll = 901700, type = 105, teacheid = 0, name = "1-9", cname = "我已死去", plot_first = "2year/2year_08", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "1_910010", front = "901707", open = "901709_901700", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200047_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "多瑙特別聯合部隊的領航，人類唯一的通感者……那位領航犧牲的時候，人類就已經沒有未來了。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1_9", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
