[901726] = {id = 901726, scroll = 901702, type = 105, teacheid = 0, name = "3-1", cname = "時間線上的交叉線", plot_first = "2year/2year_11", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "1_910011", front = "901710", open = "901727_901702,901739_901703", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200047_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "我們失敗的未來與我們還未失敗的未來，查麗莎倖存的未來與查麗莎可能死亡的未來，一切似乎都交匯於二十年前的那一天……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901727] = {id = 901727, scroll = 901702, type = 105, teacheid = 0, name = "3-2", cname = "勇者的疊加態", plot_first = "2year/2year_12", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "1_910011", front = "901726", open = "901728_901702", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200047_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "想當勇者的人都死了，但是活著的人中依舊有人想要成為勇者，這個世界最不缺的就是“死而復生”的勇者……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901728] = {id = 901728, scroll = 901702, type = 105, teacheid = 0, name = "3-3", cname = "炙手可熱", plot_first = "2year/2year_13", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "1_910011", front = "901727", open = "901729_901702", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200047_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "夜深時分，查麗莎來到我的房間，送來了一份遲到二十年的告白。那一刻，她似乎變回了二十年前的那個任性的女孩……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901729] = {id = 901729, scroll = 901702, type = 105, teacheid = 0, name = "3-4", cname = "作戰計畫", plot_first = "2year/2year_14", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "1_910011", front = "901728", open = "901730_901702", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200047_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "重新執行一份失敗過的作戰計畫，結果會有什麼不同嗎？因為存在變數——我，以及“幽靈”……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[901730] = {id = 901730, scroll = 901702, type = 105, teacheid = 0, name = "3-5", cname = "文明凋零之處", plot_first = "2year/2year_15", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "1_910011", front = "901729", open = "901731_901702", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200047_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "沒有親眼看到文明凋零的過程是種幸運，看看那些人類城市的屍骸，這是我絕對無法接受的未來……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-4", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
