[901732] = {id = 901732, scroll = 901702, type = 104, teacheid = 0, name = "3-7", cname = "拯救過去更要拯救未來", plot_first = "2year/2year_17", plot_last = "2year/2year_17e", map = "Ezn", bgm = "39-Battle-Skoll", unlock = "1_910011", front = "901731", open = "901733_901702", player = "0", monster = "600010_3_20_1_1_8_1_0_0_0_0_0_0_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_10,1_100001_1000,4_200047_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "面對“雙狼”的鉗形攻勢，勇者決心要拯救未來，於是“希望”即將從潘多拉魔盒中升起……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
