[901734] = {id = 901734, scroll = 901702, type = 104, teacheid = 0, name = "3-9", cname = "D·Z從過去到未來的幽靈", plot_first = "2year/2year_19", plot_last = "2year/2year_19e", map = "Ezn", bgm = "91-Dead_or_Alive", unlock = "1_910011", front = "901733", open = "901735_901702", player = "0", monster = "600027_3_20_1_1_8_1_0_0_0_0_0_0_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_10,1_100001_1000,4_200047_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "陰魂不散，如此形容“幽靈”再合適不過。但是我絕對無法原諒，那個高高在上的自己……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-8", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
