[902265] = {id = 902265, scroll = 902206, type = 2, teacheid = 0, name = "1-1", cname = "臨時撤退", plot_first = "Huo@dongPlot/2ZhouNian/2year_01", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "0,1", front = "0", open = "902266_902206", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "損失過半的駕駛員部隊，無法對被感染成原罪的人類駕駛員動手的幽靈部隊，以及暫時停止活動的原罪方舟……複雜的狀況使得我們暫時撤退。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1_2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902266] = {id = 902266, scroll = 902206, type = 2, teacheid = 0, name = "1-2", cname = "D型之死", plot_first = "Huo@dongPlot/2ZhouNian/2year_02", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "0,1", front = "902265", open = "902267_902206", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“所謂的擬態人格就是通過技術手段將某個活著的人格複寫進程序中，由此製造出的特殊晶片便被稱為“擬態人格”。”", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1_3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902267] = {id = 902267, scroll = 902206, type = 2, teacheid = 0, name = "1-3", cname = "女兒、女兒、以及兵器", plot_first = "Huo@dongPlot/2ZhouNian/2year_00", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "0,1", front = "902266", open = "902268_902206", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "奧德賽先生的女兒並不止一個……尼莫西妮，以及D型b2的人格數據來源……達芙妮。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902268] = {id = 902268, scroll = 902206, type = 2, teacheid = 0, name = "1-4", cname = "勇者與同伴一號", plot_first = "Huo@dongPlot/2ZhouNian/2year_03", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "0,1", front = "902267", open = "902269_902206", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "拯救世界之後，倖存的人類得給我打造一個三十米高的雕像，讚頌我，崇拜我，把我的故事永遠流傳下去。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1_4", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
