[902271] = {id = 902271, scroll = 902206, type = 2, teacheid = 0, name = "1-7", cname = "時間旅行者", plot_first = "Huo@dongPlot/2ZhouNian/2year_06", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "0,1", front = "902270", open = "902272_902206", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "我是勇者，只是撿到一個時間旅行者也沒什麼好大驚小怪的吧。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1_7", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902272] = {id = 902272, scroll = 902206, type = 2, teacheid = 0, name = "1-8", cname = "抱著貓的少女", plot_first = "Huo@dongPlot/2ZhouNian/2year_07", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "0,1", front = "902271", open = "902273_902206", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "我們在新切斯頓遇上的第一名居民，是位捧著貓咪的女孩。她正用打量某種少見外來生物（某種意義上沒錯）的目光上下掃視我。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1_8", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902273] = {id = 902273, scroll = 902206, type = 2, teacheid = 0, name = "1-9", cname = "我已死去", plot_first = "Huo@dongPlot/2ZhouNian/2year_08", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "0,1", front = "902272", open = "902274_902206", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "多瑙特別聯合部隊的領航，人類唯一的通感者……那位領航犧牲的時候，人類就已經沒有未來了。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1_9", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902274] = {id = 902274, scroll = 902206, type = 2, teacheid = 0, name = "1-10", cname = "新切斯頓的管理員", plot_first = "Huo@dongPlot/2ZhouNian/2year_09", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "0,1", front = "902273", open = "902275_902206", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "——查麗莎·德·羅蘭，原艾吉斯王牌駕駛員。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1_10", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902275] = {id = 902275, scroll = 902206, type = 2, teacheid = 0, name = "1-11", cname = "好久不見", plot_first = "Huo@dongPlot/2ZhouNian/2year_10", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "0,1", front = "902274", open = "902276_902206", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "她的變化比我想像中要少得多，還是跟以前一樣的長髮，只是頭髮變得更長了，也沒有以前那麼鮮亮了，這或許就是時間流逝帶來的成熟感吧。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C1_11", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902276] = {id = 902276, scroll = 902206, type = 2, teacheid = 0, name = "1-12", cname = "時間線上的交叉線", plot_first = "Huo@dongPlot/2ZhouNian/2year_11", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "0,1", front = "902275", open = "902277_902206", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "我們失敗的未來與我們還未失敗的未來，查麗莎倖存的未來與查麗莎可能死亡的未來，一切似乎都交匯於二十年前的那一天……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902277] = {id = 902277, scroll = 902206, type = 2, teacheid = 0, name = "1-13", cname = "勇者的疊加態", plot_first = "Huo@dongPlot/2ZhouNian/2year_12", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "0,1", front = "902276", open = "902278_902206", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "想當勇者的人都死了，但是活著的人中依舊有人想要成為勇者，這個世界最不缺的就是“死而復生”的勇者……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902278] = {id = 902278, scroll = 902206, type = 2, teacheid = 0, name = "1-14", cname = "炙手可熱", plot_first = "Huo@dongPlot/2ZhouNian/2year_13", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "0,1", front = "902277", open = "902279_902206", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "夜深時分，查麗莎來到我的房間，送來了一份遲到二十年的告白。那一刻，她似乎變回了二十年前的那個任性的女孩……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902279] = {id = 902279, scroll = 902206, type = 2, teacheid = 0, name = "1-15", cname = "作戰計畫", plot_first = "Huo@dongPlot/2ZhouNian/2year_14", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "0,1", front = "902278", open = "902280_902206", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "重新執行一份失敗過的作戰計畫，結果會有什麼不同嗎？因為存在變數——我，以及“幽靈”……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902280] = {id = 902280, scroll = 902206, type = 2, teacheid = 0, name = "1-16", cname = "文明凋零之處", plot_first = "Huo@dongPlot/2ZhouNian/2year_15", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "0,1", front = "902279", open = "902281_902206", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "沒有親眼看到文明凋零的過程是種幸運，看看那些人類城市的屍骸，這是我絕對無法接受的未來……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-4", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902281] = {id = 902281, scroll = 902206, type = 2, teacheid = 0, name = "1-17", cname = "舊敵·舊敵", plot_first = "Huo@dongPlot/2ZhouNian/2year_16", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "0,1", front = "902280", open = "902282_902206", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“斯庫爾”，准罪級原罪，曾經的手下敗將……原來不止一只嗎？……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-5", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902282] = {id = 902282, scroll = 902206, type = 15, teacheid = 0, name = "1-18", cname = "拯救過去更要拯救未來", plot_first = "Huo@dongPlot/2ZhouNian/2year_17", plot_last = "Huo@dongPlot/2ZhouNian/2year_17e", map = "Ezn", bgm = "39-Battle-Skoll", unlock = "0,1", front = "902281", open = "902283_902206", player = "0", monster = "600010_3_20_1_1_8_1_0_0_0_0_0_0_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "面對“雙狼”的鉗形攻勢，勇者決心要拯救未來，於是“希望”即將從潘多拉魔盒中升起……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902283] = {id = 902283, scroll = 902206, type = 998, teacheid = 0, name = "1-19", cname = "故地重遊", plot_first = "0", plot_last = "Huo@dongPlot/2ZhouNian/2year_18", map = "Ezn", bgm = "70-Battle_Fenrir", unlock = "0,1", front = "902282", open = "902284_902206", player = "14004_6_100_1_9_0_1_0_0_0_0_0_0_0;11052_6_100_1_9_0_1_0_0_0_0_0_0_0", monster = "600021_3_20_1_1_8_1_0_0_0_0_0_0_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "重返故地，並沒有重逢的感動，只覺到時間的荒蕪……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 1, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-7", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902284] = {id = 902284, scroll = 902206, type = 15, teacheid = 0, name = "1-20", cname = "D·Z從過去到未來的幽靈", plot_first = "Huo@dongPlot/2ZhouNian/2year_19", plot_last = "Huo@dongPlot/2ZhouNian/2year_19e", map = "Ezn", bgm = "91-Dead_or_Alive", unlock = "0,1", front = "902283", open = "902285_902206", player = "0", monster = "600027_3_20_1_1_8_1_0_0_0_0_0_0_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "陰魂不散，如此形容“幽靈”再合適不過。但是我絕對無法原諒，那個高高在上的自己……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-8", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902285] = {id = 902285, scroll = 902206, type = 2, teacheid = 0, name = "1-21", cname = "與未來對峙", plot_first = "Huo@dongPlot/2ZhouNian/2year_20", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "0,1", front = "902284", open = "902286_902206", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "那藏在“幽靈”之下的真身，毀滅世界的罪魁禍首，人類的叛徒，原罪的幫兇……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-9", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902286] = {id = 902286, scroll = 902206, type = 2, teacheid = 0, name = "1-22", cname = "最後的希望", plot_first = "Huo@dongPlot/2ZhouNian/2year_21", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "0,1", front = "902285", open = "902287_902206", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "避難所裏藏著回到過去的辦法，但如果沒有，我希望能給這個世界留下一點希望……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-10", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902287] = {id = 902287, scroll = 902206, type = 2, teacheid = 0, name = "1-23", cname = "最終話：勇者，斯珀絲如是說", plot_first = "Huo@dongPlot/2ZhouNian/2year_22", plot_last = "0", map = "0", bgm = "40-Battle-Maya", unlock = "0,1", front = "902286", open = "902288_902206", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“我送你回去，你幫我拯救世界。”勇者，斯珀絲如是說……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/C2-11", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
