[902100] = {id = 902100, scroll = 902100, type = 105, teacheid = 0, name = "1-1", cname = "屁股與喫飯與女兒", plot_first = "2025_XH3/XH3_1", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910010", front = "0", open = "902101_902100,902112_902101", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200050_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "再一次出現在影之國編年史的你，從沉睡中醒來發現自己被某位女主角捆綁了，這位女主角自稱是他的女兒——", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902101] = {id = 902101, scroll = 902100, type = 105, teacheid = 0, name = "1-2", cname = "天上一天，地上一年", plot_first = "2025_XH3/XH3_2", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910010", front = "902100", open = "902102_902100", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200050_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "據女兒（？）所説，這次在女主角宇宙可以待一年時間。“就讓我們在賸下的時間裏好好相處吧，爸爸。”", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902102] = {id = 902102, scroll = 902100, type = 105, teacheid = 0, name = "1-3", cname = "又有錢又年輕的爸爸", plot_first = "2025_XH3/XH3_3", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910010", front = "902101", open = "902103_902100", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200050_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“爸爸從來沒有帶我來遊樂園玩過，所以我從小時候就一直很憧憬。”她訴説著這樣的話，想要你和她一起去遊樂園玩。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902103] = {id = 902103, scroll = 902100, type = 105, teacheid = 0, name = "1-4", cname = "【宇宙大災】red", plot_first = "2025_XH3/XH3_4", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910010", front = "902102", open = "902104_902100", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200050_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "據説她以【人類的感情】作為食物，如果不想被她吸干變成行尸走肉的話，就不要和她正面交鋒……是非常危險的【宇宙大災】。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_4", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902104] = {id = 902104, scroll = 902100, type = 105, teacheid = 0, name = "1-5", cname = "曾經與現在的災難", plot_first = "2025_XH3/XH3_5", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910010", front = "902103", open = "902105_902100", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200050_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "我red雖然是【宇宙大災】，但是我是人類的夥伴啊！！", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_5", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902105] = {id = 902105, scroll = 902100, type = 105, teacheid = 0, name = "1-6", cname = "【宇宙大災】魔王", plot_first = "2025_XH3/XH3_6", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910010", front = "902104", open = "902106_902100", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200050_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“我想要做，就做了。”少女這麽説著，向宇宙發起了叛逆。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
