[902107] = {id = 902107, scroll = 902100, type = 105, teacheid = 0, name = "1-8", cname = "魔王的弱點", plot_first = "2025_XH3/XH3_8", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "1_910010", front = "902106", open = "902108_902100", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200050_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "那是被自詡勇者的女主角畱下的傷口……也是魔王唯一的弱點……！", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_8", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
