[902167] = {id = 902167, scroll = 902106, type = 2, teacheid = 0, name = "1-1", cname = "屁股與喫飯與女兒", plot_first = "Huo@dongPlot/2025_XH3/XH3_1", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "0", open = "902168_902106", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "再一次出現在影之國編年史的你，從沉睡中醒來發現自己被某位女主角捆綁了，這位女主角自稱是他的女兒——", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902168] = {id = 902168, scroll = 902106, type = 2, teacheid = 0, name = "1-2", cname = "天上一天，地上一年", plot_first = "Huo@dongPlot/2025_XH3/XH3_2", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "902167", open = "902169_902106", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "據女兒（？）所説，這次在女主角宇宙可以待一年時間。“就讓我們在賸下的時間裏好好相處吧，爸爸。”", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902169] = {id = 902169, scroll = 902106, type = 2, teacheid = 0, name = "1-3", cname = "又有錢又年輕的爸爸", plot_first = "Huo@dongPlot/2025_XH3/XH3_3", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "902168", open = "902170_902106", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“爸爸從來沒有帶我來遊樂園玩過，所以我從小時候就一直很憧憬。”她訴説著這樣的話，想要你和她一起去遊樂園玩。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
