[902178] = {id = 902178, scroll = 902106, type = 2, teacheid = 0, name = "1-12", cname = "幻想希望的日子", plot_first = "Huo@dongPlot/2025_XH3/XH3_12", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "902177", open = "902179_902106", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“只要我一直贏下去，人類就會得救，這些都會有的。”對美好未來的幻想，這是少女堅持下去的唯一動力。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_12", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902179] = {id = 902179, scroll = 902106, type = 2, teacheid = 0, name = "1-13", cname = "幕間其二", plot_first = "Huo@dongPlot/2025_XH3/XH3_13", plot_last = "0", map = "0", bgm = "76-Ready_or_not", unlock = "0,1", front = "902178", open = "902180_902106", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "“距離我和爸爸媽媽被困在隧道裏已經過去了6天，大家雖然心情沉重，但任然在滿懷希望地等待著救援。”", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_13", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
