[902300] = {id = 902300, scroll = 902300, type = 105, teacheid = 0, name = "1-1", cname = "冬日午後", plot_first = "2025_christmas/2025_christmas_01", plot_last = "0", map = "0", bgm = "106_Everwitner", unlock = "1_910010", front = "0", open = "902301_902300,902310_902301", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200058_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "掙脫不請自來的夢，在冷空氣的包裹中失手打翻牀頭的水杯——綜上所述，只是她生活中一个平平無奇的清晨。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902301] = {id = 902301, scroll = 902300, type = 105, teacheid = 0, name = "1-2", cname = "調制飲料，不變人生", plot_first = "2025_christmas/2025_christmas_02", plot_last = "0", map = "0", bgm = "106_Everwitner", unlock = "1_910010", front = "902300", open = "902302_902300", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200058_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "對大部分人來説的平凡周五，某个人命途多舛的寶貴假日。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902302] = {id = 902302, scroll = 902300, type = 105, teacheid = 0, name = "1-3", cname = "致親愛的我——", plot_first = "2025_christmas/2025_christmas_03", plot_last = "0", map = "0", bgm = "106_Everwitner", unlock = "1_910010", front = "902301", open = "902303_902300", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200058_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "不是每个人的生命都能在襁褓和親人的環繞下開始的。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902303] = {id = 902303, scroll = 902300, type = 105, teacheid = 0, name = "1-4", cname = "偶遇，以及偶遇", plot_first = "2025_christmas/2025_christmas_04", plot_last = "0", map = "0", bgm = "106_Everwitner", unlock = "1_910010", front = "902302", open = "902304_902300", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200058_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "起初，沒有人覺得這一晚的相遇裏存在任何命運的必然。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_4", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902304] = {id = 902304, scroll = 902300, type = 105, teacheid = 0, name = "1-5", cname = "停滯的人", plot_first = "2025_christmas/2025_christmas_05", plot_last = "0", map = "0", bgm = "106_Everwitner", unlock = "1_910010", front = "902303", open = "902305_902300", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200058_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "只從一位好鄰居的角度來説，她做的事總是無可挑剔。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_5", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902305] = {id = 902305, scroll = 902300, type = 105, teacheid = 0, name = "1-6", cname = "轉動的齒輪", plot_first = "2025_christmas/2025_christmas_06", plot_last = "0", map = "0", bgm = "106_Everwitner", unlock = "1_910010", front = "902304", open = "902306_902300", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200058_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "那一天，伊斯卡拉習慣使然地撞上了（其實還挺重要的）命運", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902306] = {id = 902306, scroll = 902300, type = 105, teacheid = 0, name = "1-7", cname = "緩步向前；被迫回首", plot_first = "2025_christmas/2025_christmas_07", plot_last = "0", map = "0", bgm = "106_Everwitner", unlock = "1_910010", front = "902305", open = "902307_902300", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200058_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "人确實不會總能知道朋友的生活具體有了什麽變化。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_7", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902307] = {id = 902307, scroll = 902300, type = 105, teacheid = 0, name = "1-8", cname = "夜談", plot_first = "2025_christmas/2025_christmas_08", plot_last = "0", map = "0", bgm = "106_Everwitner", unlock = "1_910010", front = "902306", open = "902308_902300", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200058_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "壞消息，麻煩大了。好消息，她從來不懂什麽叫獨善其身。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_8", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
