[902325] = {id = 902325, scroll = 902302, type = 105, teacheid = 0, name = "3-1", cname = "安宁不再", plot_first = "2025_christmas/2025_christmas_11", plot_last = "0", map = "0", bgm = "106_Everwitner", unlock = "1_910011", front = "902309", open = "902326_902302,902342_902303", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200058_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "麻煩，是唯一永遠會如約定那樣找上門來的東西。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_11", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902326] = {id = 902326, scroll = 902302, type = 105, teacheid = 0, name = "3-2", cname = "贵客来访", plot_first = "2025_christmas/2025_christmas_12", plot_last = "0", map = "0", bgm = "106_Everwitner", unlock = "1_910011", front = "902325", open = "902327_902302", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200058_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "一年都不會發生幾件大事的那棟辦公樓有了意外的客人。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_12", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902327] = {id = 902327, scroll = 902302, type = 105, teacheid = 0, name = "3-3", cname = "一千个灰暗的日子", plot_first = "2025_christmas/2025_christmas_13", plot_last = "0", map = "0", bgm = "106_Everwitner", unlock = "1_910011", front = "902326", open = "902328_902302", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200058_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "她依稀記得，那段日子裏，工作起碼不算自己睡不好覺的直接原因。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_13", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902328] = {id = 902328, scroll = 902302, type = 105, teacheid = 0, name = "3-4", cname = "合流", plot_first = "2025_christmas/2025_christmas_14", plot_last = "0", map = "0", bgm = "106_Everwitner", unlock = "1_910011", front = "902327", open = "902329_902302", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200058_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "一个順利過頭的計劃有可能會把當事人自己甩在後面。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_14", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902329] = {id = 902329, scroll = 902302, type = 105, teacheid = 0, name = "3-5", cname = "冰川之下", plot_first = "2025_christmas/2025_christmas_15", plot_last = "0", map = "0", bgm = "106_Everwitner", unlock = "1_910011", front = "902328", open = "902330_902302", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200058_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "那些身處臺面之下的人往往能有更多的行動空間——對敵對友都是如此。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_15", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902330] = {id = 902330, scroll = 902302, type = 105, teacheid = 0, name = "3-6", cname = "一时兴起", plot_first = "2025_christmas/2025_christmas_16", plot_last = "0", map = "0", bgm = "106_Everwitner", unlock = "1_910011", front = "902329", open = "902331_902302", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200058_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "保護欲、責任心——在上訴這一切之前，她只感覺到一股令人煩躁的熟悉。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_16", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902331] = {id = 902331, scroll = 902302, type = 105, teacheid = 0, name = "3-7", cname = "入口", plot_first = "2025_christmas/2025_christmas_17", plot_last = "0", map = "0", bgm = "106_Everwitner", unlock = "1_910011", front = "902330", open = "902332_902302", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200058_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "無論是答案還是過去，都像在招手一般陳列在那裏。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_17", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902332] = {id = 902332, scroll = 902302, type = 105, teacheid = 0, name = "3-8", cname = "祸不单行", plot_first = "2025_christmas/2025_christmas_18", plot_last = "0", map = "0", bgm = "106_Everwitner", unlock = "1_910011", front = "902331", open = "902333_902302", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200058_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "生活總會變著法子推人一把，哪怕是以絶對會把人惹毛的方式。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_18", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
[902333] = {id = 902333, scroll = 902302, type = 105, teacheid = 0, name = "3-9", cname = "各司其职", plot_first = "2025_christmas/2025_christmas_19", plot_last = "0", map = "0", bgm = "106_Everwitner", unlock = "1_910011", front = "902332", open = "902334_902302", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_1000,4_200058_30", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "想要掙脫過去的人，無法擁有過去的人，以及厭惡著過去的人。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/Summer2/bgpic/Img_Level_b1_19", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", thumbnail_drawing = "0", levelbg = "0", levelicon = "0", leveltext = "0", "0", "0", "0", "0"},
